-- Node: gw-start (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Weakness Hub - Sick Check First","body":"**⚠️ 5 DO NOT MISS:**\n1. **Neuromuscular respiratory failure (GBS, myasthenic crisis, botulism)** — single-breath count, NIF/FVC.\n2. **Hyperkalemia / severe electrolyte derangement** — ECG now, but a **normal ECG does not exclude life-threatening hyperkalemia**. Send the potassium regardless.\n3. **Acute coronary syndrome / occult sepsis** — weakness as an atypical presentation in elderly/diabetic.\n4. **Stroke / cord compression** — localize: asymmetry, sensory level, bowel/bladder.\n5. **Adrenal crisis / profound [hypoglycemia](#/tree/hypoglycemia) / tox (beta-blocker, CCB, digoxin)** — glucose, cortisol context, med review.\n\nOpen first:\n- [Hub Steps Summary](#/info/gw-steps)\n- [Hub Stop / Pitfalls](#/info/gw-stop)\n\n**First 60 seconds:**\n- Is this true motor weakness, fatigue, dizziness, pain-limited movement, or altered mental status?\n- Airway/breathing: voice strength, single breath count if neuromuscular concern, work of breathing, aspiration risk.\n- Vitals trend: fever, hypotension, tachy/brady, hypoxia, hypothermia/hyperthermia.\n- Fingerstick glucose now.\n- ECG early: hyperkalemia/hypokalemia, ischemia, dysrhythmia, QRS/QTc toxicity.\n- Quick neuro localization: face/arm/leg asymmetry, speech, gaze, pupils, reflexes, gait if safe.\n- Medication/toxin scan: sedatives, beta-blocker/CCB, insulin/sulfonylurea, statin, diuretic, lithium, alcohol/withdrawal.\n\n**Sort the complaint before you sort the differential:**\n- **True motor weakness** (measurable power loss) → localize with the exclusions below.\n- **Proximal-predominant pattern** (trouble rising from a chair, arms overhead, waddling gait) → [Proximal Weakness Hub](#/tree/proximal-weakness-hub).\n- **\"Not acting right,\" functional decline, off legs, generally unwell** — especially age >65 → [Generally Unwell Elderly Hub](#/tree/nonspecific-unwell-elderly-hub). This is the highest-miss branch: nonspecific complaints in older ED patients carry acute morbidity in the majority, and the underlying diagnosis is far more often sepsis, ACS, occult infection, drug effect, or metabolic derangement than a primary neuromuscular disease.\n\nGeneralized weakness is a trap complaint. Stabilize physiology and localize before labeling it benign.","citation":[1,2,3,12,13,14,16,20,24,25],"next":"gw-exclusions","summary":"Glucose, ECG, vitals, airway/respiratory strength, meds/tox, and localization first.","safetyLevel":"critical"}'::jsonb
WHERE id = 'gw-start' AND tree_id = 'generalized-weakness-hub';

-- Node: gw-exclusions (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Time-Critical Exclusions - Pick the Best Fit","body":"Pick the first dangerous lane. You can return after the immediate action.","citation":[1,2,3,4,5,6,12,13],"options":[{"label":"Hypotension, fever, rigors, dehydration, poor perfusion, lactate concern","description":"Shock / sepsis / severe volume problem","next":"gw-shock","urgency":"critical"},{"label":"Face/arm/leg asymmetry, aphasia, gaze, neglect, acute gait change - OR diplopia, dysarthria, vertigo, crossed/bilateral findings, fluctuating consciousness","description":"Stroke/ICH mimic, true neurovascular weakness, or posterior-circulation/basilar syndrome","next":"gw-neurovascular","urgency":"critical"},{"label":"Ascending weakness, areflexia, bulbar symptoms, weak cough, dyspnea","description":"GBS / myasthenic crisis / neuromuscular respiratory risk","next":"gw-neuromuscular","urgency":"critical"},{"label":"Paralysis, cramps, diuretic/renal/dialysis risk, any ECG change - or a normal ECG with those risks","description":"K/Na/Ca/Mg/Phos derangement","next":"gw-electrolyte","urgency":"critical"},{"label":"Kussmaul, dehydration, thyroid/adrenal clues, hypothermia, hyperthermia","description":"DKA/HHS, thyroid, adrenal, heat/cold illness","next":"gw-endocrine","urgency":"urgent"},{"label":"Chest discomfort, dyspnea, syncope, palpitations, pallor, melena","description":"ACS/dysrhythmia/anemia/bleeding presenting as weakness","next":"gw-cardiac-anemia","urgency":"critical"},{"label":"Sedation, overdose, acidosis, osm gap, CO exposure, medication change","description":"Toxicologic or medication-induced weakness","next":"gw-tox","urgency":"critical"},{"label":"No immediate exclusion hit","description":"Initial weakness bundle and reassess","next":"gw-rescue"}],"summary":"Shock, stroke, neuromuscular respiratory risk, electrolytes, endocrine, cardiac/anemia, and tox are the first exclusions.","safetyLevel":"critical"}'::jsonb
WHERE id = 'gw-exclusions' AND tree_id = 'generalized-weakness-hub';

-- Node: gw-neurovascular (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Neurovascular Weakness","body":"Open [Acute Ischemic Stroke](#/tree/stroke), [ICH](#/tree/ich), [Cervical Artery Dissection](#/tree/cervical-artery-dissection), or [Altered Mental Status Hub](#/tree/altered-mental-status-hub) as appropriate.\n\n**Next 5 minutes:** glucose corrected/confirmed, last-known-well, NIHSS-style focused exam, CT/CTA/perfusion per stroke workflow, BP strategy by diagnosis, anticoagulant/reversal history.\n\n**Pitfall:** generalized weakness can hide a focal deficit when the patient is tired, aphasic, neglectful, or unable to walk safely.\n\n**The posterior-circulation trap:** hemispheric stroke almost never presents as *generalized* weakness — but **basilar occlusion / bilateral pontine infarct can**, and it is the one stroke that legitimately looks like undifferentiated weakness. Suspect it when there is bilateral or quadriparetic weakness, crossed findings (cranial nerve on one side, long tract on the other), diplopia, dysconjugate gaze, dysarthria, dysphagia, vertigo/ataxia, or waxing-and-waning consciousness. NIHSS badly under-scores posterior strokes, and a non-contrast CT is frequently normal. If the story fits, the imaging question is **CTA head/neck**, not CT alone.\n\n**The other non-brain \"stroke\":** a cord lesion — compression, [cauda equina](#/tree/cauda-equina), [transverse myelitis](#/tree/transverse-myelitis), or anterior spinal artery infarct — produces bilateral weakness with a sensory level and bladder/bowel change. Check a sensory level, saddle sensation, rectal tone, and a post-void residual before you accept \"generalized weakness.\"","citation":[4,5,13],"recommendation":"If the exam localizes, activate the stroke/bleed workflow.","confidence":"definitive","safetyLevel":"critical"}'::jsonb
WHERE id = 'gw-neurovascular' AND tree_id = 'generalized-weakness-hub';

-- Node: gw-neuromuscular (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"GBS / Myasthenia / Neuromuscular Respiratory Risk","body":"Open [Guillain-Barre Syndrome](#/tree/guillain-barre) or [Myasthenia Gravis](#/tree/myasthenia-gravis).\n\n**Next 5 minutes:** assess bulbar symptoms, cough, secretion handling, neck flexion, single breath count or bedside respiratory mechanics if available, cardiac monitoring for dysautonomia, avoid premature discharge even if pulse ox is normal.\n\n**Danger signs:** rapidly progressive weakness, inability to walk, facial/bulbar weakness, autonomic instability, weak cough, rising CO2, or fatigue with repeated exam.\n\n**Differential for progressive weakness (each competitor breaks one GBS pillar — ascending, symmetric, areflexic, sensation spared):**\n- **[Transverse myelitis](#/tree/transverse-myelitis)** — fever, faster onset, early bladder/bowel dysfunction, a sensory level. *Clear it:* map a sensory level, screen for retention; MRI cord confirms.\n- **[Cauda equina](#/tree/cauda-equina) / cord compression** — back pain at a level, saddle anesthesia, retention, often asymmetric. *Clear it:* rectal tone, saddle sensation, post-void residual. In a known-cancer patient, think metastatic cord compression ([Oncological Emergencies](#/tree/oncological-emergencies)).\n- **[Myasthenia gravis](#/tree/myasthenia-gravis)** — insidious, ocular/bulbar onset, fatigable; **reflexes preserved**. *Clear it:* sustained upgaze/fatigability, ice-pack test. Intact reflexes is the key separator.\n- **[Botulism](#/tree/botulism)** — **descending** weakness, early bulbar palsy, dilated/poorly reactive pupils. *Clear it:* direction of progression + pupil exam; source hx (canned food, wound, infant honey).\n- **[Tick paralysis](#/tree/tick-paralysis)** — ascending and areflexic too (a true mimic), but CSF is normal. *Clear it:* full skin/scalp/hairline exam to find and remove the tick — removal reverses it.\n- **[Lambert-Eaton (LEMS)](#/tree/lambert-eaton)** — proximal weakness that **improves with use**, dry mouth, paraneoplastic. *Clear it:* facilitation history, reflexes augment post-exercise; hunt for small cell lung cancer.\n- **Vascular (cord infarct / brainstem stroke)** — usually painful, asymmetric, UMN signs, crossed/cranial-nerve findings, +/- absent pulses. *Clear it:* hyperreflexia, Babinski, CN crossing; MRI confirms.\n- **[B12 deficiency](#/tree/b12-deficiency) / neuropathy / B1 deficiency** — prominent **sensory** deficits, dorsal-column signs (proprioception/vibration loss), brisk reflexes if SCD; GBS sensation is often near-normal. *Clear it:* sensory level, B12/folate labs.\n\n**A normal LP does not exclude GBS.** Albuminocytologic dissociation (raised CSF protein with a normal cell count) is time-dependent, not present at onset. In the 1,231-patient IGOS cohort it was present in only 57% when the LP was done within 4 days of weakness onset, rising to 84% after day 4; protein is normal in roughly 30-50% of patients during the first week. Early in the course the LP is mainly there to *exclude* the mimics (leptomeningeal malignancy, infection, cord/root inflammation) — marked pleocytosis (>50 cells/uL) argues against GBS. GBS remains a clinical diagnosis made on serial exams; do not let a reassuring CSF protein send a progressively weak patient home.\n\n**Two cheap moves that prevent the embarrassing misses:** actually look for a tick, and check the [potassium](#/tree/potassium).","citation":[8,9,12,13,16,17,22,23,27],"recommendation":"Normal SpO2 does not clear neuromuscular respiratory failure. Trend ventilation and bulbar safety.","confidence":"recommended","safetyLevel":"critical"}'::jsonb
WHERE id = 'gw-neuromuscular' AND tree_id = 'generalized-weakness-hub';

-- Node: gw-electrolyte (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Electrolyte Paralysis / Weakness","body":"Open [Potassium Disorders](#/tree/potassium), [Sodium Disorders](#/tree/sodium), [Calcium Disorders](#/tree/calcium-disorders), [Phosphorous Disorders](#/tree/phosphorus-disorders), or [Magnesium Disorders](#/tree/magnesium-disorders).\n\n**Next 5 minutes:** ECG first, BMP/Mg/Phos/Ca, renal function, CK if [rhabdomyolysis](#/tree/rhabdomyolysis) concern. Treat unstable ECG hyperkalemia immediately with calcium. Severe symptomatic hyponatremia with seizure/coma follows hypertonic saline pathway. Severe hypoK/hypoPhos/hypoMg can present as profound weakness or respiratory failure.\n\n**Pitfall:** do not wait for the full lab panel when ECG shows dangerous potassium physiology.\n\n**⚠️ The bigger pitfall - a normal ECG does not exclude life-threatening hyperkalemia.** The ECG is *insensitive* for the diagnosis: in the classic 90-patient review of admitted patients with K+ >=6.0, the ECG performed poorly and no diagnostic T-wave threshold could be established. Patients have arrested with unremarkable tracings, and the KDIGO emergency-medicine consensus states plainly that a normal ECG should not be regarded as reassuring. The ECG earns its place as a **risk-stratification and treat-now trigger** - QRS prolongation, bradycardia <50, and junctional rhythm mark the patients heading for a short-term adverse event - **not as a rule-out test**. In a dialysis miss, an AKI, a crush injury, or a patient on an ACE inhibitor/ARB/spironolactone/trimethoprim, send the potassium and act on the number, not on a clean strip.\n\n**Two paralysis syndromes that hide behind a potassium value:**\n- **Thyrotoxic periodic paralysis** - acute painless proximal or near-total flaccid paralysis with profound hypokalemia, sensation/bowel/bladder intact, classically a young Asian or Hispanic male after a carbohydrate load, heavy exertion, or alcohol. Total body potassium is **normal**; the potassium has shifted intracellularly, so this is a shift problem, not a deficit. Check a TSH/free T4 on any unexplained hypokalemic paralysis and open [Thyroid Disorders](#/tree/thyroid) alongside [Potassium Disorders](#/tree/potassium). Repletion here carries a rebound-hyperkalemia risk as the shift reverses - follow the dosing and monitoring in the potassium consult rather than reflexively loading potassium.\n- **Hypercalcemia and hypermagnesemia** - both blunt neuromuscular transmission and present as weakness, areflexia, and lethargy rather than as an electrolyte complaint. Hypermagnesemia is nearly always iatrogenic (eclampsia infusions, Mg-containing cathartics/antacids in renal failure).","citation":[1,2,14,15,20,21,26],"recommendation":"ECG-dangerous electrolyte disorders are treated before complete diagnostic certainty.","confidence":"recommended","safetyLevel":"critical"}'::jsonb
WHERE id = 'gw-electrolyte' AND tree_id = 'generalized-weakness-hub';

-- Node: gw-endocrine (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Endocrine / Metabolic Weakness","body":"Open [DKA](#/tree/dka), [Adrenal Insufficiency](#/tree/adrenal-insufficiency), [Thyroid Disorders](#/tree/thyroid), [Hypoglycemia](#/tree/hypoglycemia), [Heat Stroke](#/tree/heat-stroke), or [Hypothermia](#/tree/hypothermia) when the phenotype fits.\n\n**Next 5 minutes:** VBG/chemistry/ketones for DKA/HHS, potassium before insulin, temperature, TSH/free T4 if thyroid storm/myxedema clues, empiric hydrocortisone if adrenal crisis is plausible with shock/hypoglycemia/hyponatremia.\n\n**Pitfall:** fatigue plus hypotension/hypoglycemia/hyponatremia after steroid exposure or adrenal disease is adrenal crisis until proven otherwise. Do not delay the glucocorticoid to confirm the diagnosis - a short course of parenteral steroid is safe even if adrenal insufficiency is later excluded, and the confirmatory cortisol can be drawn on the way.\n\n**Three thyroid phenotypes that read as weakness:**\n- **Myxedema coma** - hypothermia, bradycardia, hypoventilation with hypercapnia, hyponatremia, non-pitting edema, blunted affect. The hypothermia often masks the infection that precipitated it.\n- **Thyroid storm / apathetic thyrotoxicosis** - the elderly version is not agitated and hyperkinetic; it is apathetic, weak, wasted, and in atrial fibrillation.\n- **Thyrotoxic periodic paralysis** - painless hypokalemic flaccid paralysis; see the [Electrolyte lane](#/node/gw-electrolyte).\n\n**Steroid-related weakness that is not a crisis:** chronic glucocorticoid exposure produces a painless proximal myopathy with a normal CK - see [Proximal Weakness Hub](#/tree/proximal-weakness-hub).","citation":[10,18],"recommendation":"Correct the life-threatening physiology while the endocrine workup runs.","confidence":"recommended","safetyLevel":"critical"}'::jsonb
WHERE id = 'gw-endocrine' AND tree_id = 'generalized-weakness-hub';

-- Node: gw-cardiac-anemia (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Cardiac / Dysrhythmia / Anemia / Bleeding","body":"Open [Chest Pain Hub](#/tree/chest-pain-hub), [STEMI](#/tree/stemi), [NSTEMI](#/tree/nstemi), [A-Fib RVR](#/tree/afib-rvr), or [GI Bleed Hub](#/tree/gi-bleed-hub) when symptoms, ECG, or bleeding history point that way.\n\n**Next 5 minutes:** ECG, troponin if ischemia possible, orthostatics if safe, CBC, rectal/bleeding history when anemia/GI bleed plausible, POCUS when shock or dyspnea coexists.\n\n**Pitfall:** MI, dysrhythmia, GI bleed, and severe anemia often present as weakness in older adults, diabetics, and patients with limited symptom reporting. In the >434,000-patient National Registry of Myocardial Infarction, about **one third of confirmed MIs presented without chest pain** - and those patients skewed older, female, and diabetic, presented later, were treated less aggressively, and died at roughly twice the in-hospital rate. Weakness, dyspnea, and fatigue are among the substitute presentations. A single normal ECG does not close the question when the story is right.","citation":[1,11,13,25,28],"recommendation":"Weakness with ECG change, syncope, dyspnea, pallor, or bleeding history needs cardiac/bleeding workup.","confidence":"recommended","safetyLevel":"critical"}'::jsonb
WHERE id = 'gw-cardiac-anemia' AND tree_id = 'generalized-weakness-hub';

-- Node: gw-tox (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Toxicologic / Medication Weakness","body":"Open [TCA Toxidrome](#/tree/tca-toxidrome), [Calcium Channel Blocker Overdose](#/tree/ccb-od), [Beta-Blocker Overdose](#/tree/beta-blocker-od), [Digoxin Toxicity](#/tree/digoxin-toxicity), [Salicylate Toxicity](#/tree/salicylate), [Toxic Alcohols](#/tree/toxic-alcohols), [CO Toxicity](#/tree/co-toxicity), or the [Unknown Ingestion Hub](#/tree/unknown-ingestion-hub) when clues fit.\n\n**Next 5 minutes:** ECG for QRS/QTc/bradycardia, glucose, VBG/anion gap/osm gap, acetaminophen/salicylate levels when ingestion possible, co-oximetry if exposure risk, medication reconciliation, poison center early.\n\n**Pitfall:** urine drug screen rarely explains weakness. ECG, glucose, acid-base, and medication list change care faster.\n\n**The medication list is the test.** In older adults the commonest reversible cause of \"generalized weakness\" is not an exotic toxidrome, it is the pharmacy: a new or up-titrated beta-blocker or CCB (bradycardia, fatigue), a diuretic or laxative (hypokalemia, volume depletion), an ACE inhibitor/ARB/spironolactone/trimethoprim (hyperkalemia), a sulfonylurea or insulin (recurrent hypoglycemia), a statin (myopathy - check a CK), a benzodiazepine/opioid/anticholinergic (sedation misread as weakness), digoxin in new renal failure, or lithium in volume depletion. Ask what changed in the last two weeks.\n\n**Neuromuscular blockade by drug:** aminoglycosides, high-dose magnesium, and organophosphate/carbamate exposure all produce genuine neuromuscular weakness that can progress to respiratory failure. Organophosphates come with the cholinergic toxidrome (SLUDGE, miosis, fasciculations, bronchorrhea) - the bronchorrhea kills, not the weakness.","citation":[1,6,13],"recommendation":"Use ECG and acid-base physiology to find dangerous tox causes.","confidence":"recommended","safetyLevel":"critical"}'::jsonb
WHERE id = 'gw-tox' AND tree_id = 'generalized-weakness-hub';

-- Node: gw-rescue (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Rescue / Initial Bundle + Reassess","body":"**Default bundle when no killer has declared itself:**\n- Glucose, ECG, monitor if ill.\n- CBC, CMP (potassium, sodium, calcium, renal function), Mg, Phos, CK when myopathy/rhabdo possible.\n- UA/CXR/cultures only when infection clues exist; do not shotgun without exam signal.\n- Orthostatic vitals and ambulation test when safe.\n- Medication reconciliation, recent illness, tick/travel, exertion, dialysis, insulin/sulfonylurea, diuretics.\n- Focused neuro exam repeated after fluids, glucose correction, analgesia, or rest.\n\n**⚠️ Do not let a positive urine end the workup in an older adult.** Asymptomatic bacteriuria is common with age, and IDSA specifically recommends assessment for other causes and observation - not antibiotics - in older patients with functional or cognitive impairment who have bacteriuria plus confusion or a fall but no localizing genitourinary symptoms and no systemic signs of infection. \"UTI\" is the single most common anchoring diagnosis that lets an occult sepsis, ACS, bleed, or drug effect walk out of the department. (A bacteriuric patient who is febrile or hemodynamically unstable without a localizing source is a different patient - treat broadly and hunt the source.)\n\n**If the complaint was never true motor weakness,** switch hubs rather than repeating the same panel: [Generally Unwell Elderly Hub](#/tree/nonspecific-unwell-elderly-hub) for functional decline / \"not acting right,\" [Dizziness Hub](#/tree/dizziness-hub) for lightheadedness or vertigo mislabeled as weakness, [Syncope](#/tree/syncope) for transient loss of consciousness, and [Altered Mental Status Hub](#/tree/altered-mental-status-hub) when cognition is the real deficit.\n\n**Reassess in 30-60 minutes:** ability to stand/walk, symmetric strength, reflexes, bulbar/respiratory symptoms, vitals, ECG/lab changes.","citation":[1,2,3,12,13,24,25,29],"next":"gw-reassess","summary":"Glucose/ECG/labs, meds, focused neuro, orthostatics/ambulation, then reassess.","safetyLevel":"warning"}'::jsonb
WHERE id = 'gw-rescue' AND tree_id = 'generalized-weakness-hub';

