INSERT INTO tree_citations (tree_id, num, text) VALUES ('generalized-weakness-hub', 10, 'Umpierrez GE, Davis GM, ElSayed NA, et al. Hyperglycemic Crises in Adults With Diabetes: A Consensus Report. Diabetes Care. 2024;47(8):1257-1275. doi:10.2337/dci24-0032. PMID:39052901. Co-published: Diabetologia. 2024;67(8):1455-1479. PMID:38907161');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('generalized-weakness-hub', 11, 'Gulati M, Levy PD, Mukherjee D, et al. 2021 AHA/ACC/ASE/CHEST/SAEM/SCCT/SCMR Guideline for the Evaluation and Diagnosis of Chest Pain. J Am Coll Cardiol. 2021;78(22):e187-e285. doi:10.1016/j.jacc.2021.07.053. PMID:34756653');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('generalized-weakness-hub', 12, 'Ganti L, Rastogi V. Acute Generalized Weakness. Emerg Med Clin North Am. 2016;34(4):795-809. doi:10.1016/j.emc.2016.06.006. PMID:27741989');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('generalized-weakness-hub', 13, 'Sams W, Hassan N, Meurer WJ. General Approach to Weakness. Emerg Med Clin North Am. 2026;44(1):219-226. doi:10.1016/j.emc.2025.08.013. PMID:41260854');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('generalized-weakness-hub', 14, 'Lindner G, Burdmann EA, Clase CM, et al. Acute hyperkalemia in the emergency department: a summary from a Kidney Disease: Improving Global Outcomes conference. Eur J Emerg Med. 2020;27(5):329-337. doi:10.1097/MEJ.0000000000000691. PMID:32852924. PMCID:PMC7448835');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('generalized-weakness-hub', 15, 'Verbalis JG, Goldsmith SR, Greenberg A, et al. Diagnosis, evaluation, and treatment of hyponatremia: expert panel recommendations. Am J Med. 2013;126(10 Suppl 1):S1-S42. doi:10.1016/j.amjmed.2013.07.006. PMID:24074529');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('generalized-weakness-hub', 16, 'Lawn ND, Fletcher DD, Henderson RD, Wolter TD, Wijdicks EFM. Anticipating mechanical ventilation in Guillain-Barre syndrome. Arch Neurol. 2001;58(6):893-898. doi:10.1001/archneur.58.6.893. PMID:11405803. Source of the 20/30/40 rule (vital capacity <20 mL/kg, maximal inspiratory pressure <30 cmH2O, maximal expiratory pressure <40 cmH2O). Single-center retrospective cohort (1976-1996); should not be the sole trigger for intubation.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('generalized-weakness-hub', 17, 'Narayanaswami P, Sanders DB, Wolfe G, et al. International Consensus Guidance for Management of Myasthenia Gravis: 2020 Update. Neurology. 2021;96(3):114-122. doi:10.1212/WNL.0000000000011124. PMID:33144515');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('generalized-weakness-hub', 18, 'Bornstein SR, Allolio B, Arlt W, et al. Diagnosis and Treatment of Primary Adrenal Insufficiency: An Endocrine Society Clinical Practice Guideline. J Clin Endocrinol Metab. 2016;101(2):364-389. doi:10.1210/jc.2015-1710. PMID:26760044. PMCID:PMC4880116');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('generalized-weakness-hub', 19, 'Prescott HC, Antonelli M, Alhazzani W, et al. Surviving Sepsis Campaign: International Guidelines for Management of Sepsis and Septic Shock 2026. Crit Care Med. 2026;54(4):725-812. doi:10.1097/CCM.0000000000007075. PMID:41869847. Current version; supersedes ref 7.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('generalized-weakness-hub', 20, 'Montague BT, Ouellette JR, Buller GK. Retrospective review of the frequency of ECG changes in hyperkalemia. Clin J Am Soc Nephrol. 2008;3(2):324-330. doi:10.2215/CJN.04611007. PMID:18235147. PMCID:PMC2390954. Basis for the statement that the ECG is INSENSITIVE for hyperkalemia: in 90 admitted patients with K+ >=6.0 mEq/L the ECG performed poorly and no diagnostic T-wave threshold could be established. Single-center retrospective review.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('generalized-weakness-hub', 21, 'Durfey N, Lehnhof B, Bergeson A, et al. Severe hyperkalemia: can the electrocardiogram risk stratify for short-term adverse events? West J Emerg Med. 2017;18(5):963-971. doi:10.5811/westjem.2017.6.33033. PMID:28874951. PMCID:PMC5576635. SCOPE NOTE: this study supports the ECG as a RISK-STRATIFICATION tool (QRS prolongation, bradycardia <50, and junctional rhythm marked patients heading for a short-term adverse event); it does NOT establish the ECG as a rule-out test, and it is frequently mis-cited as evidence that the ECG is insensitive for hyperkalemia. That insensitivity claim belongs to refs 20 and 14, not to this paper.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('generalized-weakness-hub', 22, 'van Doorn PA, Van den Bergh PYK, Hadden RDM, et al. European Academy of Neurology / Peripheral Nerve Society guideline on diagnosis and treatment of Guillain-Barre syndrome. Eur J Neurol. 2023;30(12):3646-3674. doi:10.1111/ene.16073. PMID:37814552. GRADE-based current guideline; updates ref 8.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('generalized-weakness-hub', 23, 'Al-Hakem H, Doets AY, Stino AM, et al. CSF findings in relation to clinical characteristics, subtype, and disease course in patients with Guillain-Barre syndrome. Neurology. 2023;100(23):e2386-e2397. doi:10.1212/WNL.0000000000207282. PMID:37643890. PMCID:PMC10256127. Erratum in Neurology. 2023;101(13):592. IGOS cohort, n=1,231: albuminocytologic dissociation present in 57% when the lumbar puncture was performed within 4 days of weakness onset vs 84% after day 4; the authors state that normal protein levels do not exclude the diagnosis.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('generalized-weakness-hub', 24, 'Nemec M, Koller MT, Nickel CH, et al. Patients presenting to the emergency department with non-specific complaints: the Basel Non-specific Complaints (BANC) study. Acad Emerg Med. 2010;17(3):284-292. doi:10.1111/j.1553-2712.2009.00658.x. PMID:20370761. Prospective cohort establishing that non-specific complaints (weakness, generally unwell, functional decline) in older ED patients carry a high rate of acute morbidity.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('generalized-weakness-hub', 25, 'Herzog SM, Jenny MA, Nickel CH, Nieves Ortega R, Bingisser R. Predicting risk of serious medical conditions in emergency department patients with nonspecific complaints. PLoS One. 2020;15(11):e0239902. doi:10.1371/journal.pone.0239902. PMID:33152015. PMCID:PMC7643999');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('generalized-weakness-hub', 26, 'Correia M, Darocki M, Tovar Hirashima E. Changing management guidelines in thyrotoxic hypokalemic periodic paralysis. J Emerg Med. 2018;55(2):252-256. doi:10.1016/j.jemermed.2018.04.063. PMID:29871829. Basis for the rebound-hyperkalemia caution: potassium is shifted intracellularly rather than depleted, so aggressive repletion risks rebound hyperkalemia as the shift reverses.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('generalized-weakness-hub', 27, 'Doets AY, Walgaard C, Lingsma HF, et al. International validation of the Erasmus Guillain-Barre syndrome respiratory insufficiency score. Ann Neurol. 2022;91(4):521-531. doi:10.1002/ana.26312. PMID:35106830. PMCID:PMC9302662');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('generalized-weakness-hub', 28, 'Canto JG, Shlipak MG, Rogers WJ, et al. Prevalence, clinical characteristics, and mortality among patients with myocardial infarction presenting without chest pain. JAMA. 2000;283(24):3223-3229. doi:10.1001/jama.283.24.3223. PMID:10866870. National Registry of Myocardial Infarction 2: of 434,877 confirmed MIs, one third presented without chest pain; those patients were older, more often female and diabetic, presented later, were treated less aggressively, and had roughly twice the in-hospital mortality.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('generalized-weakness-hub', 29, 'Nicolle LE, Gupta K, Bradley SF, et al. Clinical practice guideline for the management of asymptomatic bacteriuria: 2019 update by the Infectious Diseases Society of America. Clin Infect Dis. 2019;68(10):e83-e110. doi:10.1093/cid/ciy1121. PMID:30895288. Basis for not reflexively treating bacteriuria in older adults with functional or cognitive impairment who have delirium or a fall but no localizing genitourinary symptoms and no systemic signs of infection: IDSA recommends assessment for other causes and observation rather than antimicrobials.');

-- Node: gib-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"GI Bleed Hub — Sick Check First","body":"**⚠️ 5 DO NOT MISS:**\n1. **Hemorrhagic shock / massive bleed** — shock index >1, ongoing hematemesis; activate MTP.\n2. **Variceal hemorrhage** — cirrhosis stigmata; octreotide + antibiotics + early endoscopy.\n3. **Aortoenteric fistula** — prior aortic graft + GI bleed = catastrophic until excluded.\n4. **Brisk upper bleed presenting as hematochezia** — 10–15%, more shocky; place an NG/assess. Caveat: a negative NG aspirate excludes NOTHING (≈42% sensitive for source; negative in up to 15% of actively bleeding UGIB) — EGD is the proving step, not the tube. [3, 4]\n5. **Anticoagulant/antiplatelet-driven bleed** — identify agent; reverse where indicated.\n\nWalk into the room. Before any source-finding, sort sick vs not-sick.\n\nOpen first:\n\n- [Hub Steps Summary](#/info/gib-steps)\n- [Hub Stop / Pitfalls](#/info/gib-stop)\n\n**Scan in 30 seconds:** [1, 2]\n\n- **General appearance** — pale, diaphoretic, end-of-bed ill, altered, vomiting blood at the door?\n- **Vitals trend** (not single snapshot) — tachycardia, hypotension, narrow pulse pressure, orthostatic drop, hypoxia\n- **Shock index** = HR / SBP — >1.0 = ongoing blood loss, >1.4 = massive hemorrhage posture\n- **Mental status** — confused / drowsy = hypoperfusion or hepatic encephalopathy\n- **Skin / stigmata** — jaundice, spider angiomata, caput, palmar erythema (cirrhosis), purpura (coag), Telangiectasias (HHT)\n- **Abdomen at the door** — distended (ascites), tender (perforation/ischemia), pulsatile mass (AAA aortoenteric fistula)\n- **Rectal exam early** — confirms melena vs hematochezia vs occult vs nothing\n\n**If ANY of:** hypotension, ongoing hematemesis, melena + tachycardia, altered, lactate >4, end-of-life appearance — **start resus parallel to workup.** Bay 1, IV × 2 large-bore (16 g+), monitor, type and cross 4-6 units, lactate, [Massive Transfusion Protocol](#/tree/massive-transfusion) ready. Permissive hypotension target SBP 90-100 until source controlled.\n\n**Four-question screen** (drives Module 2):\n\n1. **Hematemesis or coffee-grounds?** → upper source until proven otherwise\n2. **Melena (black, tarry, foul)?** → upper source ~90% of the time (transit >14 h)\n3. **Hematochezia (bright red blood per rectum)?** → lower source usually, BUT brisk upper bleed can present as hematochezia in 10-15% (more shocky)\n4. **Cirrhosis, varices, alcohol use, recent NSAID/anticoag/antiplatelet?** → variceal vs PUD vs anticoag-driven changes management\n\n**Continue → Time-Critical Exclusions**","citation":[1,2,3],"next":"gib-exclusions","summary":"Look, count, feel — then commit. Shock index >1 = ongoing loss. Rectal exam now.","safetyLevel":"critical"}'::jsonb
WHERE id = 'gib-start' AND tree_id = 'gi-bleed-hub';

-- Node: gib-exc-ugib (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Upper GI Bleed Pathway","body":"Open [Upper GI Bleed](#/tree/upper-gi-bleed) consult. Glasgow-Blatchford for triage, variceal vs non-variceal cascade, endoscopy timing.\n\n**Recognize fast:** [4]\n\n- Hematemesis (red blood = active variceal or arterial; coffee-grounds = older blood, less brisk)\n- Cirrhotic stigmata: jaundice, spider angiomata, caput, ascites, palmar erythema\n- Risk factors: NSAID, ASA, anticoag, prior PUD, prior varices, H. pylori, EtOH binge\n- Melena alone (no vomiting) is still upper ~90%\n\n**Next 5 minutes:** [4, 5]\n\n- CBC, CMP, coags, type and cross 2-6 units (more if shock)\n- BUN/Cr ratio >30 favors upper source (digested protein bolus)\n- 2 large-bore IVs, NPO, PPI bolus + drip (pantoprazole 80 mg IV then 8 mg/h). ACG 2021 accepts high-dose PPI given continuously OR intermittently (80 mg bolus then 40 mg 2-4×/day) — outcomes equivalent. Note ACG 2021 could reach NO recommendation for or against PRE-endoscopic PPI. [3]\n- Erythromycin 250 mg IV 20-90 min before EGD (ACG 2021 conditional rec) — improves visualization and diagnostic yield and reduces repeat endoscopy; no proven effect on rebleeding or mortality. [3]\n- **If cirrhotic or suspected variceal:** add octreotide 50 mcg IV bolus then 50 mcg/h infusion (continue 2-5 days once portal hypertensive bleeding confirmed, per Baveno VII and AASLD 2024) + ceftriaxone 1 g IV (SBP prophylaxis, mortality benefit) [5, 22]\n- Glasgow-Blatchford ≤1 in stable patients → outpatient pathway feasible per institutional protocol. ACG 2021 (conditional): GBS 0-1 should be DISCHARGED with outpatient follow-up rather than admitted — inpatient endoscopy is not a prerequisite. [3]\n- NG lavage NOT routinely needed (negative does not exclude UGIB)\n- **Endoscopy timing:** within 24 h of presentation, after resuscitation. ACG 2021 deliberately dropped the old <12 h suggestion for NONvariceal UGIB — Lau (NEJM 2020, n=516, GBS ≥12) found urgent (<6 h) endoscopy did NOT lower 30-day mortality (8.9% vs 6.6%, p=0.34) and rebleeding was numerically worse. Stabilize first. Variceal bleeding is the exception: <12 h per Baveno VII / ESGE. [3, 21, 22]\n- Massive hematemesis → call GI for emergent endoscopy + IR backup\n\n**Disposition:** ICU if shock, ongoing bleeding, severe coag, cirrhosis with high-risk lesion. Floor if stable post-endoscopy with Forrest IIc/III or low-risk variceal. Discharge only after endoscopy if Glasgow-Blatchford ≤1 + clean lesion + reliable follow-up.","citation":[3,4,5,21,22],"summary":"Open [Upper GI Bleed](#/tree/upper-gi-bleed) — Glasgow-Blatchford triage, PPI, octreotide + ceftriaxone if variceal, endoscopy timing.","safetyLevel":"critical"}'::jsonb
WHERE id = 'gib-exc-ugib' AND tree_id = 'gi-bleed-hub';

-- Node: gib-exc-lgib (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Lower GI Bleed Pathway","body":"Open [Lower GI Bleed](#/tree/lower-gi-bleed) consult. Oakland score for triage, CTA vs colonoscopy timing, embolization decision.\n\n**Red flag — brisk upper bleed presenting as hematochezia:** 10-15% of hematochezia in shocky patients is upper source. Check the four-question screen before committing to lower pathway:\n\n1. Hemodynamically unstable + hematochezia? → suspect brisk upper, place NG and/or send for urgent EGD before colonoscopy. EGD is the proving step — a negative NG aspirate does NOT rule out an upper source (up to 15% of actively bleeding UGIB have a negative aspirate). Exception: prior aortic graft → CTA first, not EGD. [3]\n2. Coffee-ground emesis or hematemesis ever during this episode? → upper\n3. Known varices, cirrhosis, recent NSAID/ASA/anticoag? → upper more likely\n4. BUN/Cr ratio >30? → upper\n\n**Next 5 minutes:** [6]\n\n- CBC, CMP, coags, type and cross 2-4 units\n- 2 large-bore IVs, NPO\n- Oakland score (age, sex, prior LGIB, DRE findings, HR, SBP, Hgb) — ≤8 = outpatient candidate, >8 = admit\n- Massive hematochezia + shock → CTA first, then IR embolization or urgent colonoscopy depending on findings\n- Stable → colonoscopy within 24 h with bowel prep\n- ⚠️ **ACG 2023 UPDATE (strong recommendation, moderate-quality evidence): perform a NONEMERGENT inpatient colonoscopy.** Urgent colonoscopy within 24 h has NOT been shown to improve rebleeding, mortality, transfusion requirement, or length of stay. Reserve urgent colonoscopy for ongoing hemodynamically significant bleeding not controlled by resuscitation. The [Lower GI Bleed](#/tree/lower-gi-bleed) consult carries the current ACG 2023 timing pathway — follow it over the 24 h figure above. [2]\n\n**Disposition:** ICU if shock or active bleeding. Floor if stable for colonoscopy. Outpatient only if Oakland ≤8 + reliable follow-up.","citation":[2,3,6],"summary":"Open [Lower GI Bleed](#/tree/lower-gi-bleed) — Oakland score, but rule out brisk upper first if shocky.","safetyLevel":"critical"}'::jsonb
WHERE id = 'gib-exc-lgib' AND tree_id = 'gi-bleed-hub';

-- Node: gib-exc-massive (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Massive GI Hemorrhage","body":"Activate [Massive Transfusion Protocol](#/tree/massive-transfusion). Shock index >1.4, ongoing exsanguination, or anticipated need for >10 units in 24 h.\n\n**Targets:** [10]\n\n- 1:1:1 RBC:plasma:platelets ratio (start with the first balanced cooler)\n- TXA 1 g IV over 10 min (within 3 h of bleed onset) + 1 g over 8 h — strongest data in trauma. ⚠️ **This does NOT extrapolate to GI bleeding, and TXA is not low-harm here.** HALT-IT (n=12,009) found no reduction in death from bleeding (4% vs 4%; RR 0.99, 95% CI 0.82-1.18) plus MORE harm: VTE 0.8% vs 0.4% (RR 1.85, 95% CI 1.15-2.98) and seizures 0.6% vs 0.4% (RR 1.73, 95% CI 1.03-2.93). ACG 2023 issues a STRONG recommendation AGAINST antifibrinolytics in GI bleeding, and the HALT-IT investigators concluded TXA should not be used for GI bleeding outside a randomised trial. The sibling [Lower GI Bleed](#/tree/lower-gi-bleed) consult states do NOT give TXA. [2, 10]\n- Calcium replacement (citrate chelation from transfused blood causes hypocalcemia — give CaCl 1 g IV every 4 units)\n- Permissive hypotension SBP 90-100 mmHg until source controlled (do not over-resuscitate before hemostasis)\n- Avoid hypothermia (lethal triad)\n- Avoid acidosis (lactic acid + dilutional)\n- Empirical IR / endoscopy / surgery activation — do not wait for stability\n\n**Source-specific:**\n\n- Variceal: octreotide (continue 2-5 days once portal hypertensive bleeding is confirmed) + ceftriaxone 1 g IV + emergent EGD with banding, or balloon tamponade (Blakemore/Minnesota tube) as a bridge. AASLD 2024: assess candidacy for **preemptive TIPS** at initial presentation — in selected high-risk patients it improves both bleeding control and survival. [5, 22]\n- Non-variceal upper: pantoprazole drip + EGD with clip/cautery/epinephrine\n- Lower: CTA + IR embolization OR urgent colonoscopy\n- Aorto-enteric fistula: emergent vascular surgery + CT angiography\n\n**HALT-IT note:** the 12,009-patient HALT-IT trial (2020 Lancet) showed TXA did not reduce death from bleeding in upper or lower GI bleed and INCREASED both venous thromboembolic events (RR 1.85) and seizures (RR 1.73). Use TXA selectively in true massive hemorrhage with hemodynamic instability; do NOT give TXA to every GI bleeder. Note that ACG 2023 goes further than \"selectively\" — it is a STRONG recommendation AGAINST antifibrinolytics in GI bleeding, and no guideline currently endorses routine TXA for GI hemorrhage. [2, 10]","citation":[2,5,10,11,22],"summary":"Activate [MTP](#/tree/massive-transfusion). 1:1:1 ratio. TXA selectively (HALT-IT cautions in GI bleed). Permissive hypotension until source control.","safetyLevel":"critical"}'::jsonb
WHERE id = 'gib-exc-massive' AND tree_id = 'gi-bleed-hub';

-- Node: gib-exc-mesenteric (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Mesenteric Ischemia + GI Bleed","body":"Open [Mesenteric Ischemia](#/tree/mesenteric-ischemia) consult. Pain out of proportion + AF / vasculopath / postprandial pain + GI bleed = mesenteric ischemia until proven otherwise.\n\n**Why this matters:** [14]\n\n- Colonoscopy in active mesenteric ischemia can perforate ischemic bowel\n- Resus alone delays the lethal diagnosis\n- Lactate may be normal early (5-15% have normal lactate at presentation in arterial mesenteric ischemia) — treat lactate as a LATE marker of transmural infarction, never as a rule-out. A normal lactate does not exclude AMI. Get the CTA. [14]\n- D-dimer is sensitive but non-specific\n\n**Workup:**\n\n- CTA mesenteric with arterial + portal venous phases — gold standard, do this BEFORE colonoscopy\n- Empirical heparin if AF or arterial thromboembolism suspected (and no contraindication)\n- Vascular surgery + IR consult\n- NPO, broad-spectrum antibiotics (bowel ischemia → bacterial translocation)\n\n**Patterns:**\n\n- Acute arterial (embolic) — sudden severe pain, AF, prior embolism\n- Acute arterial (thrombotic) — gradual onset, atherosclerosis, postprandial pain history\n- Mesenteric venous thrombosis — younger, hypercoagulable, subacute\n- NOMI (non-occlusive) — shock, vasopressors, cocaine, ergotism\n\nGI bleed can be the lead symptom in any of these. Don''t let the bleed anchor you to a colonoscopy-first pathway.","citation":[14,15],"summary":"Open [Mesenteric Ischemia](#/tree/mesenteric-ischemia) — CTA before colonoscopy. Pain out of proportion + bleed.","safetyLevel":"critical"}'::jsonb
WHERE id = 'gib-exc-mesenteric' AND tree_id = 'gi-bleed-hub';

-- Node: gib-rescue (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Initial Bundle (Stable, Undifferentiated)","body":"**Bundle for the stable, undifferentiated GI bleeder.** Use while waiting for the source pattern to declare.\n\n**Resus:**\n\n- 2 large-bore IVs (16 g+), NPO\n- Type and cross 2-4 units\n- **Transfusion threshold: restrictive, Hgb <7 g/dL; <8 g/dL is reasonable with pre-existing cardiovascular disease.** Villanueva (NEJM 2013, n=921) showed lower 45-day mortality and less rebleeding with the restrictive strategy, most strongly in Child-Pugh A/B cirrhotics — over-transfusion raises portal pressure and worsens variceal bleeding. Transfuse earlier in the exsanguinating, hemodynamically unstable patient. [3, 20]\n- Initial fluid bolus 500-1000 mL LR (avoid over-resuscitation; dilutes coag factors)\n- Permissive hypotension (SBP 90-100) until hemostasis\n\n**Labs:** [4, 6]\n\n- CBC (baseline Hgb may UNDER-estimate active bleed before hemodilution)\n- BMP/CMP (BUN/Cr ratio >30 suggests upper)\n- INR/PTT, fibrinogen\n- Lactate (perfusion + ischemia)\n- Type and cross 2-4 units\n- LFTs (cirrhotic vs not)\n- Lipase (if abdominal pain)\n- Troponin + ECG (demand ischemia in anemic patients, esp. age >50)\n\n**Meds while waiting:**\n\n- Pantoprazole 80 mg IV bolus + 8 mg/h drip (any presumed UGIB). ACG 2021 accepts intermittent high-dose PPI (80 mg bolus then 40 mg 2-4×/day) as an equivalent alternative to the drip, and could reach NO recommendation for or against PRE-endoscopic PPI at all — do not let the drip delay resuscitation or the scope. [3]\n- Octreotide 50 mcg IV bolus + 50 mcg/h drip (continue 2-5 days once portal hypertensive bleeding is confirmed) + ceftriaxone 1 g IV — if any concern for variceal bleed [5, 22]\n- Erythromycin 250 mg IV 20-90 min before a planned EGD — prokinetic, clears the gastric field, improves diagnostic yield (ACG 2021 conditional rec) [3]\n- Hold NSAIDs, antiplatelets, anticoagulants pending reversal decision\n- ⚠️ Do NOT add TXA to this bundle. ACG 2023 gives a STRONG recommendation against antifibrinolytics in GI bleeding; HALT-IT showed no mortality benefit with more VTE and seizures. [2, 10]\n- Antiemetic (ondansetron 4-8 mg IV) — vomiting can worsen variceal bleed\n\n**Risk stratification scores:**\n\n- Glasgow-Blatchford (UGIB) — ≤1 → outpatient consideration\n- Oakland (LGIB) — ≤8 → outpatient consideration\n- Rockall (UGIB post-endoscopy)\n- Shock index = HR/SBP — >1 = ongoing loss\n\n**Continue → Reassess at 30-60 minutes**","citation":[2,3,4,5,6,10,20,22],"next":"gib-rescue-reassess","summary":"Bundle = IVs + NPO + T&C + PPI + octreotide if cirrhotic + risk score. Permissive hypotension until hemostasis.","safetyLevel":"critical"}'::jsonb
WHERE id = 'gib-rescue' AND tree_id = 'gi-bleed-hub';

-- Node: gib-imaging (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Imaging + Source Control Strategy","body":"**Match imaging to phenotype — don''t shotgun.**\n\n**Upper source suspected:**\n\n- Endoscopy (EGD) — within 24 h for stable, 12 h for cirrhotic, ASAP for shock or active bleed [4]\n- ⚠️ Do NOT chase a sub-12 h scope in NONvariceal UGIB. ACG 2021 deliberately deleted the 2012 \"<12 h may be considered\" language; Lau (NEJM 2020, n=516, GBS ≥12) found urgent (<6 h) endoscopy did not lower 30-day mortality (8.9% vs 6.6%, p=0.34) and rebleeding was numerically worse. Resuscitate and correct comorbidities first, then scope within 24 h. The 12 h window is a VARICEAL quality indicator (Baveno VII / ESGE), not a general UGIB target. [3, 21, 22]\n- Erythromycin 250 mg IV 20-90 min pre-EGD as a prokinetic to clear the gastric field — improves visualization and diagnostic yield, reduces repeat endoscopy (ACG 2021 conditional rec) [3]\n- CT angiography if endoscopy non-diagnostic or unable\n\n**Lower source suspected, stable:**\n\n- Colonoscopy within 24 h with bowel prep [6]\n- ⚠️ **ACG 2023 supersedes that timing (strong recommendation, moderate-quality evidence): NONEMERGENT inpatient colonoscopy.** Urgent colonoscopy within 24 h does not improve rebleeding, mortality, transfusion requirement, or length of stay; in stable patients colonoscopy within 14 days is as effective as within 24 h. Reserve urgent colonoscopy for ongoing hemodynamically significant bleeding not controlled by resuscitation. [2]\n- CT angiography if active bleed and unable to prep\n\n**Lower source suspected, unstable / massive bleed:**\n\n- CTA first (85-90% sensitive for active bleeding at rates ≥0.3-0.5 mL/min) [2]\n- IR embolization if active extravasation localized\n- Urgent colonoscopy if CTA negative but bleeding ongoing\n- Surgery if both fail (rare)\n\n**Aorto-enteric fistula suspected:**\n\n- CTA arterial + delayed phases\n- Vascular surgery NOW\n\n**Mesenteric ischemia suspected:**\n\n- CTA arterial + portal venous phases\n- Vascular surgery + IR\n\n**Capsule endoscopy / push enteroscopy:**\n\n- For obscure GI bleed (negative EGD + colonoscopy)\n- Inpatient or outpatient depending on stability\n\n**Tagged RBC scan / nuclear scintigraphy:**\n\n- Slow intermittent bleeding (>0.1 mL/min)\n- Less useful in acute setting; can localize roughly\n\n**Continue → Disposition**","citation":[2,3,4,5,6,21,22],"next":"gib-dispo","summary":"Phenotype drives imaging. EGD for upper, colonoscopy for lower stable, CTA for unstable lower, CTA + vascular for AEF/mesenteric.","safetyLevel":"critical"}'::jsonb
WHERE id = 'gib-imaging' AND tree_id = 'gi-bleed-hub';

-- Node: gib-dispo-icu (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"ICU Admit","body":"**ICU criteria:**\n\n- Hemodynamic instability (SBP <90, shock index >1)\n- Ongoing active bleed\n- Massive transfusion activation\n- Cirrhotic with variceal bleed (high mortality)\n- Forrest Ia/Ib lesion post-endoscopy\n- Aorto-enteric fistula\n- Mesenteric ischemia\n\n**ICU bundle:**\n\n- Arterial line, central line if pressors needed\n- Continuous monitoring, serial Hgb q4-6h\n- Standing PPI drip + octreotide if variceal\n- Ceftriaxone 1 g IV daily for cirrhotic (SBP prophylaxis x 7 days). AASLD 2024 now caps this at up to 5 days and stops it once bleeding is controlled with no active infection; ESGE 2022 and the 2017 AASLD guidance allow up to 7 days. Tailor to local resistance patterns. [5, 22]\n- Coordinated GI + IR + surgery on call\n- DVT prophylaxis decision: mechanical (SCDs) safe; pharmacologic held until 24-48 h hemostatic\n\n[Massive Transfusion Protocol](#/tree/massive-transfusion) if criteria still met.","citation":[4,5,6,10,22],"summary":"ICU for shock, ongoing bleed, MTP, variceal cirrhotic, AEF, mesenteric. Bundle includes PPI drip + octreotide + ceftriaxone if variceal.","safetyLevel":"critical"}'::jsonb
WHERE id = 'gib-dispo-icu' AND tree_id = 'gi-bleed-hub';

