-- Node: hh-triage (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Rule In / Rule Out — Pick the Thread to Walk","body":"Ask history-first. Each option opens a short chain that walks a validated rule or a tight clinical gate to an explicit verdict. If a cause is EXCLUDED you loop back here to walk the next thread. When every dangerous thread is cleared and the pattern matches prior benign HA → Rescue.","citation":[1,7,4,5,6],"options":[{"label":"First-ever / worst-of-life / thunderclap (peak <1 min)","description":"SAH — walk the Ottawa SAH Rule, then CT ± LP","next":"hh-sah-entry","urgency":"critical"},{"label":"Focal deficit, AMS, or new seizure","description":"Stroke / ICH / status / mass / encephalitis — image + consult","next":"hh-neuro-entry","urgency":"critical"},{"label":"Fever + meningeal signs OR immunocompromised","description":"Bacterial meningitis — antibiotics within 60 min","next":"hh-mening-entry","urgency":"critical"},{"label":"Painful red eye + halos around lights + nausea","description":"AACG — IOP now, no mydriatics, no dim lights","next":"hh-aacg-entry","urgency":"critical"},{"label":"Winter heater / indoor fuel-burner / multiple sick at one address","description":"CO toxicity — co-oximetry (SpO₂ lies), 100% NRB now","next":"hh-co-entry","urgency":"critical"},{"label":"Age ≥50 + new HA + jaw claudication / scalp tenderness / vision change","description":"GCA — ESR/CRP + empiric steroid before biopsy","next":"hh-gca-entry","urgency":"urgent"},{"label":"Neck pain + Horner OR recent neck trauma / manipulation","description":"Cervical artery dissection — CTA neck","next":"hh-dissection-entry","urgency":"urgent"},{"label":"Papilledema, seizure, or hypercoag risk (postpartum / OCP / thrombophilia)","description":"CVST — MRV or CT venogram","next":"hh-cvst-entry","urgency":"urgent"},{"label":"Pregnant or postpartum","description":"Pre-eclampsia / CVST / RCVS / apoplexy all on the table","next":"hh-preg-entry","urgency":"urgent"},{"label":"Recent trauma","description":"Walk the Canadian CT Head Rule","next":"hh-trauma-entry","urgency":"urgent"},{"label":"Severe unilateral periorbital + ipsilateral autonomic + restless","description":"Cluster — 100% O₂ NRB while transitioning","next":"hh-cluster-entry","urgency":"urgent"},{"label":"Electric-shock V2/V3 face pain triggered by touch / chewing / cold","description":"Trigeminal neuralgia — HLA-B*1502 screen before CBZ","next":"hh-tn-entry"},{"label":"All dangerous threads cleared — pattern matches prior benign HA","description":"Rescue cocktail + reassess at 60-90 min","next":"hh-rescue"}],"summary":"Walk each dangerous thread to a verdict. Excluded loops back here. All clear + benign pattern → Rescue.","safetyLevel":"critical"}'::jsonb
WHERE id = 'hh-triage' AND tree_id = 'headache-hub';

-- Node: hh-sah-entry (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"SAH — Ottawa SAH Rule","body":"The **Ottawa SAH Rule** applies to alert (GCS 15) patients **older than 15 years** with a new SEVERE non-traumatic headache reaching MAXIMUM intensity within 1 hour, presenting within 14 days of onset, with no head trauma in the preceding 7 days.\n\n🛑 **Do NOT apply the rule to:** new focal neurologic deficit · papilledema on fundoscopy · known aneurysm, prior SAH, or known brain tumor · an established recurrent headache syndrome (≥3 similar episodes over ≥6 months) · return visit for the same headache already worked up with CT + LP.\n\n**The rule is 100% sensitive for SAH (95% CI 94.6-100) but only ~13-15% specific.** It is a rule-OUT instrument only. A POSITIVE rule does not mean SAH — it means the patient is not cleared by the rule and now needs a clinical decision about imaging. Investigate if ANY of these is present:","citation":[5,6,16,7],"options":[{"label":"ANY high-risk feature present","description":"Age ≥40 · neck pain/stiffness · witnessed LOC · onset during exertion · thunderclap (instantly peaking) · limited neck flexion on exam","next":"hh-sah-verdict","urgency":"critical"},{"label":"NONE of the six features — rule negative","description":"Ottawa SAH Rule negative rules out SAH in this population","next":"hh-sah-excluded"}],"summary":"Ottawa SAH Rule (100% sens, ~13-15% spec — rule-OUT only): age ≥40, neck pain/stiffness, LOC, exertional onset, thunderclap, limited neck flexion.","safetyLevel":"critical"}'::jsonb
WHERE id = 'hh-sah-entry' AND tree_id = 'headache-hub';

-- Node: hh-sah-verdict (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"RULE IN — SAH Workup Now","body":"Ottawa SAH Rule positive → investigate. Open [SAH](#/tree/sah) for CT timing and LP-for-xanthochromia indications.\n\n**Non-contrast CT head:** 100% sensitive (95% CI 97-100) within 6 h of onset in the Perry prospective cohort using a third-generation scanner read by a qualified radiologist; pooled meta-analysis sensitivity 98.7% (LR- 0.01, ~1.5 misses per 1000). Sensitivity drops sharply after 6-12 h. ACEP 2019 gives a **Level A** recommendation that a normal NCCT within 6 h of onset, in a patient with a normal neuro exam, rules out non-traumatic SAH.\n\n⚠️ **The published sensitivity assumes a modern multi-detector scanner AND an experienced reader.** Community series have documented misses inside the 6 h window. If your read is not confident, do not treat the negative CT as definitive.\n\n**If CT is negative AND onset >6 h ago → LP for xanthochromia** (or CTA per local pathway).\n\n⚠️ **Xanthochromia timing:** oxyhemoglobin → bilirubin conversion takes ~12 h in vivo. An LP done in the **6-12 h window is a gap zone** — CT sensitivity has already fallen but bilirubin may not yet have formed, so a negative result there is less reassuring than it looks. Most North American labs use visual inspection (pooled sens ~83%) rather than spectrophotometry (~87%); neither is the 100% figure quoted from the older Dutch spectrophotometry series.\n\n**Next 5 minutes while transitioning:** IV access, monitor, BP control if SBP >160 (target 140-160, labetalol or nicardipine), neuro recheck q15 min, neurosurgery consult on positive CT.\n\n**If CT and CSF both negative + onset >6 h** — the thunderclap differential is not finished. Also consider:\n- **RCVS** — the single largest share of thunderclap presentations after SAH; recurrent thunderclap + vasoactive trigger (postpartum, cannabis, SSRIs, ergots, decongestants). CTA/MRA may be NORMAL in the first days — repeat vessel imaging at 1-3 weeks if suspicion is high.\n- [CVST](#/tree/cvst) — MRV or CT venogram.\n- [Cervical Artery Dissection](#/tree/cervical-artery-dissection) — CTA neck.\n- **Pituitary apoplexy** — sudden HA + visual field defect + ophthalmoplegia; the pituitary is poorly seen on CT, so MRI is often required.\n- **Colloid cyst of the third ventricle** — recurrent thunderclap triggered by postural change or Valsalva, ± drop attack / transient LOC, headache easing when supine. Acute obstructive hydrocephalus at the foramen of Monro; can kill suddenly.\n- **Spontaneous intracranial hypotension** — orthostatic headache, better lying flat; MRI with contrast shows diffuse pachymeningeal enhancement.\n- **Hypertensive emergency / PRES** — severe HTN + seizure or visual change.","citation":[5,6,7,16,25,26],"recommendation":"Open SAH consult. Non-contrast CT now (100% sens ≤6 h with modern scanner + expert read; pooled 98.7%). LP if CT negative + onset >6 h — mind the 6-12 h xanthochromia gap. BP 140-160. Neurosurgery on positive CT.","confidence":"definitive","safetyLevel":"critical"}'::jsonb
WHERE id = 'hh-sah-verdict' AND tree_id = 'headache-hub';

-- Node: hh-sah-excluded (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"SAH — Ruled Out","body":"Ottawa SAH Rule negative in an eligible patient rules out SAH (100% sensitivity, 95% CI 94.6-100, prospectively validated). No CT mandated by the rule alone.\n\n⚠️ The rule only applies to the eligible population (alert/GCS 15, **older than 15 years**, new severe headache peaking within 1 h, presenting within 14 days, no head trauma in the prior 7 days, no focal deficit, no papilledema, no known aneurysm-SAH-tumor, not an established recurrent headache syndrome). If your patient falls OUTSIDE those criteria, the rule does not clear them — image on clinical grounds.\n\n⚠️ Note the lower bound of the sensitivity confidence interval is 94.6%, not 100%. In a very high pre-test-probability patient, a negative rule is not a substitute for judgment.\n\nReturn to Rule In / Rule Out and walk the next dangerous thread.","citation":[5,6,16,7],"next":"hh-triage","recommendation":"SAH excluded by negative Ottawa rule (eligible patients only). Continue triage.","confidence":"definitive"}'::jsonb
WHERE id = 'hh-sah-excluded' AND tree_id = 'headache-hub';

-- Node: hh-mening-verdict (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"RULE IN — Antibiotics Within 60 Minutes","body":"Open [Meningitis / Encephalitis](#/tree/meningitis) for empiric selection by age + immune status, CT-before-LP indications, CSF interpretation, and steroid adjunct timing.\n\n**Empiric antibiotics target within 60 minutes of suspicion. Do NOT wait for imaging or LP.** CT before LP IS indicated for AMS / focal deficit / papilledema / immunocompromise / new-onset seizure within 1 week / history of CNS disease / age ≥60 (IDSA) — but that does NOT delay the empiric dose (draw cultures if fast, otherwise give antibiotics first).\n\n**Standard empiric (refined in the Meningitis consult):** ceftriaxone 2 g IV + vancomycin 15-20 mg/kg IV; add ampicillin 2 g IV if age <3 mo or >50 yo (Listeria); add acyclovir 10 mg/kg IV if encephalitis features. **Dexamethasone 10 mg IV with or just before the first antibiotic dose** if bacterial meningitis suspected.","citation":[7,10,11],"recommendation":"Antibiotics within 60 min + dexamethasone with/before first dose. Open Meningitis consult. Do not delay for imaging/LP.","confidence":"definitive","safetyLevel":"critical"}'::jsonb
WHERE id = 'hh-mening-verdict' AND tree_id = 'headache-hub';

-- Node: hh-co-verdict (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"RULE IN — CO Toxicity","body":"Open [CO Toxicity](#/tree/co-toxicity) for the full pathway (CO-Hgb thresholds, hyperbaric O₂ indications per UHMS 2019, pregnancy considerations).\n\n**Next 5 minutes:** keep the patient on **100% O₂ via NRB**. CO-Hgb elimination half-life is **~4-5 h on room air → ~60-90 min on high-flow 100% O₂ → ~20-30 min on hyperbaric O₂ at 2.5-3 atm**. Continue O₂ regardless of the measured level pending the result and until symptoms clear.\n\n**Hyperbaric consideration** at lower thresholds for: pregnancy, LOC, neurologic deficit, cardiac ischemia, CO-Hgb >25% (>20% in pregnancy). Remove all household members from the source; screen everyone at the address.","citation":[9,21],"recommendation":"100% NRB now. Open CO Toxicity consult. HBO for pregnancy / LOC / neuro or cardiac ischemia / high CO-Hgb.","confidence":"definitive","safetyLevel":"critical"}'::jsonb
WHERE id = 'hh-co-verdict' AND tree_id = 'headache-hub';

-- Node: hh-gca-verdict (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"RULE IN — GCA (Treat Before Biopsy)","body":"Work up and treat **IN PARALLEL — do NOT wait for biopsy to start steroid.**\n\n1. **ESR + CRP stat** (ESR usually >50; up to ~5% have normal ESR — CRP is more sensitive; check both).\n2. **Empiric high-dose corticosteroid NOW:**\n   - No visual symptoms: **prednisone 60 mg PO daily**.\n   - Visual symptoms or jaw claudication: **methylprednisolone 1 g IV daily × 3 days**, then prednisone 60 mg PO.\n3. **Ophthalmology** (visual symptoms) + **rheumatology** (biopsy + long-term management) consults.\n4. **Temporal artery biopsy within 1-2 weeks** — steroid does NOT obscure yield in that window. ACR/VF 2021 conditionally recommends an initial **UNILATERAL** biopsy over bilateral, and a **long-segment specimen (>1 cm)** over a short one (GCA is focal and segmental, so a short segment can miss it). Go to the contralateral side only if the first biopsy is negative and suspicion persists, or if symptoms are not clearly lateralized.\n\n**Why the urgency:** untreated GCA causes irreversible vision loss in ~20%; once one eye is hit, the other can follow within days.","citation":[7,13],"recommendation":"ESR + CRP + empiric high-dose steroid NOW (IV pulse if visual/jaw). Biopsy within 1-2 weeks. Ophtho for visual symptoms.","confidence":"definitive","safetyLevel":"critical"}'::jsonb
WHERE id = 'hh-gca-verdict' AND tree_id = 'headache-hub';

-- Node: hh-cvst-excluded (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"CVST — Low Probability","body":"No hypercoagulable context, no papilledema or seizure, and a normal exam make CVST low-probability. A normal D-dimer lowers the probability further but does not fully exclude it in a high-suspicion patient — image if risk factors or ICP signs surface.\n\n⚠️ **If papilledema IS present and venous imaging is negative, you are not done — think idiopathic intracranial hypertension.** Classic picture: obese woman of childbearing age, daily headache, pulsatile tinnitus, transient visual obscurations, ± CN VI palsy. Diagnosis needs an LP with a measured opening pressure (≥25 cm H₂O adults, ≥28 cm children) and NORMAL CSF composition after imaging excludes mass, hydrocephalus, and venous thrombosis. Get formal visual fields — permanent vision loss is the outcome you are preventing. Other secondary causes of raised ICP (drugs: tetracyclines, vitamin A/retinoids, withdrawal from chronic steroids) belong on the same list.\n\nReturn to Rule In / Rule Out.","citation":[7,23,30],"next":"hh-triage","recommendation":"CVST low-probability without hypercoag risk/ICP signs. Image if the picture evolves. Continue triage.","confidence":"recommended"}'::jsonb
WHERE id = 'hh-cvst-excluded' AND tree_id = 'headache-hub';

-- Node: hh-preg-verdict (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"RULE IN — Pregnancy/Postpartum Workup","body":"Work these in parallel based on findings:\n\n- **[HTN in Pregnancy / Pre-eclampsia](#/tree/htn-pregnancy)** if BP ≥140/90 + proteinuria or end-organ signs. Magnesium for seizure prophylaxis; treat severe-range BP; delivery is definitive. **ACOG: severe-range BP is ≥160 systolic OR ≥110 diastolic persisting ≥15 min — treat within 30-60 min of confirmation** (IV labetalol, IV hydralazine, or PO immediate-release nifedipine). Headache with new-onset hypertension counts as an end-organ (neurologic) feature and makes the diagnosis WITHOUT proteinuria.\n- **The postpartum window is 6 weeks, not 6 days.** Pre-eclampsia and eclampsia can present de novo up to 6 weeks after delivery — do not discount a severe postpartum headache because she has already delivered.\n- **[CVST](#/tree/cvst)** if papilledema, seizure, or focal deficit — postpartum hypercoag peaks ~3 weeks. MRV.\n- **RCVS** if recurrent thunderclap + vasoactive trigger (ergots, SSRIs, cannabis, postpartum). CTA/MRA; nimodipine per neuro. Early CTA/MRA can be NORMAL — repeat vessel imaging at 1-3 weeks if suspicion stays high.\n- **Pituitary apoplexy** if sudden severe HA + visual field defect + ophthalmoplegia.\n- **[Cervical Artery Dissection](#/tree/cervical-artery-dissection)** if neck pain + Horner — postpartum is a known window.\n\n**Imaging in pregnancy:** non-contrast CT is acceptable for life-threats (shield abdomen). MRI without gadolinium preferred when available.\n\n**Analgesia in pregnancy:** acetaminophen first-line; metoclopramide + diphenhydramine + magnesium are the safer parenteral adjuncts. Avoid ergots and valproate. **NSAIDs: FDA 2020 advisory — limit between 20 and 30 weeks, AVOID after 30 weeks.** Past 20 weeks, use them only with OB agreement and a short course.","citation":[8],"recommendation":"Pre-eclampsia (Mg + BP + OB) / CVST / RCVS / apoplexy / dissection in parallel. MRI no-gad if feasible.","confidence":"definitive","safetyLevel":"critical"}'::jsonb
WHERE id = 'hh-preg-verdict' AND tree_id = 'headache-hub';

-- Node: hh-trauma-excluded (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Post-Traumatic HA — CT Not Required","body":"Canadian CT Head Rule negative in an applicable patient — CT is not required. In the derivation cohort the five high-risk factors were **100% sensitive (95% CI 92-100) for need for neurosurgical intervention**, and all seven factors were **98.4% sensitive (95% CI 96-99) for clinically important brain injury** (the 4 missed injuries were small contusions; none needed neurosurgery, none had sequelae).\n\n⚠️ Performance degrades in **intoxicated** patients (~70% sensitivity for clinically important injury) and \"dangerous mechanism\" is a subjective criterion — apply it deliberately, not reflexively.\n\n**Chronic post-traumatic HA (>3 months) without progressive features** — conservative management + neuro/sports-medicine follow-up; persistent post-concussive syndrome is well described and does NOT warrant escalation without new red flags.\n\nReturn to Rule In / Rule Out.","citation":[15],"next":"hh-triage","recommendation":"No CT by a negative Canadian CT Head Rule (applicable patients). Conservative for chronic without progression. Continue triage.","confidence":"definitive"}'::jsonb
WHERE id = 'hh-trauma-excluded' AND tree_id = 'headache-hub';

-- Node: hh-rescue (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Rescue Cocktail — Benign-Pattern HA","body":"Every dangerous thread cleared, pattern matches prior benign HA (migraine, tension, undifferentiated). Standard parenteral cocktail (2025 AHS acute-migraine guideline, Robblee et al.):\n\n**THE COCKTAIL:**\n- [Prochlorperazine 10 mg IV](#/drug/prochlorperazine/migraine cocktail) over ~15 min — workhorse antidopaminergic, the highest-evidence parenteral agent (**2025 AHS Level A — \"should be offered\"**)\n- [Diphenhydramine 25 mg IV](#/drug/diphenhydramine/migraine cocktail) — akathisia prophylaxis (DO NOT SKIP — prochlorperazine is the worst offender)\n- [Ketorolac 15-30 mg IV](#/drug/ketorolac/migraine) — NSAID component, **2025 AHS Level B** (cap 15 mg if age ≥65, renal disease, or low body weight)\n- [Magnesium 1-2 g IV](#/drug/magnesium-sulfate/migraine) over 15 min — adjunct, best for migraine with aura and menstrual migraine\n- **1 L NS bolus** — often the most therapeutic single element\n\n**Metoclopramide alternative** if prochlorperazine is unavailable or QT is a concern: [Metoclopramide 10 mg IV](#/drug/metoclopramide/status migrainosus) — similar efficacy, slightly less akathisia (**2025 AHS Level B**).\n\n⚠️ **Know what the akathisia-prophylaxis evidence actually says.** The supporting RCT (Vinson & Drotts 2001) paired diphenhydramine **50 mg** IV with **prochlorperazine** and cut akathisia from 36% to 14% (ARR 22%, OR 0.39, p=.01). A separate RCT (Friedman 2009) paired diphenhydramine with **metoclopramide** and found NO benefit (OR 1.0, 95% CI 0.5-2.0). So: co-administer with prochlorperazine, and if you are running metoclopramide alone, do not assume diphenhydramine is protecting you — watch for restlessness and treat it if it appears.\n\n**2025 AHS also says (Level A, \"must NOT offer\"): do not give IV hydromorphone.** Sumatriptan 6 mg SC and IV ketorolac are Level B; IV dexamethasone, IV chlorpromazine, and IV valproate are Level C; IV paracetamol/acetaminophen is Level C \"should not offer\" as monotherapy.\n\n**Add-on with strong 2025 evidence:** a **greater occipital nerve block** is a **Level A \"should be offered\"** ED option in the 2025 AHS guideline (sphenopalatine block is Level B) — fast, safe, opioid-sparing (see refractory node).\n\n**Avoid:** opioids (worsen recurrence, feed medication-overuse HA), butalbital combinations (Fioricet), and repeat triptans within 24 h of any ergot.\n\n**Pregnancy:** acetaminophen IV + metoclopramide IV + diphenhydramine IV + magnesium is the safest cocktail. Avoid ergots and valproate. **NSAIDs: per the FDA 2020 advisory, limit use between 20 and 30 weeks (oligohydramnios / fetal renal risk) and AVOID entirely after 30 weeks (ductal closure).** Practically: if you are past 20 weeks, reach for something other than ketorolac.","citation":[2,14,27,28,29],"next":"hh-rescue-reassess","summary":"Prochlorperazine 10 IV + diphenhydramine 25 IV + ketorolac 15-30 IV + Mg 1-2 g + 1 L NS. Metoclopramide if unavailable. ONB is first-tier. Avoid opioids/butalbital.","safetyLevel":"warning"}'::jsonb
WHERE id = 'hh-rescue' AND tree_id = 'headache-hub';

-- Node: hh-rescue-second (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":3,"title":"Second Round / Observation","body":"**Options for partial response:**\n- Repeat [Prochlorperazine 10 mg IV](#/drug/prochlorperazine/migraine cocktail) (or switch to [Metoclopramide 10 mg IV](#/drug/metoclopramide/status migrainosus) if akathisia despite diphenhydramine)\n- Add **dexamethasone 10 mg IV** — reduces 24-72 h recurrence (NNT ~9 pooled, Colman 2008). Note the evidence grade softened: **Level B in the 2016 AHS assessment → Level C (\"may be offered\") in the 2025 AHS guideline.** Still reasonable, no longer a strong recommendation.\n- Add **valproate 500-1000 mg IV** over 10-15 min if not contraindicated (avoid pregnancy, liver disease) — **2025 AHS Level C**\n- **Chlorpromazine IV** is also 2025 AHS Level C — more sedation and hypotension, pre-load fluid\n- Repeat NS 1 L bolus if dehydrated\n- ED obs unit for 4-6 h with planned reassessment\n\n**At second reassessment (4-6 h):** improved → discharge bundle; still refractory → ONB or DHE; new neuro feature → image now.","citation":[2,14,17,27],"recommendation":"Repeat antidopaminergic, add dexamethasone, consider obs-unit reassessment at 4-6 h.","confidence":"recommended"}'::jsonb
WHERE id = 'hh-rescue-second' AND tree_id = 'headache-hub';

-- Node: hh-rescue-refractory (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":3,"title":"Refractory — ONB or DHE","body":"**Greater occipital nerve block (ONB)** — bedside, 5-15 min onset, works for status migrainosus + cluster + occipital neuralgia + cervicogenic + post-traumatic. **Level A (\"should be offered\") in the 2025 AHS ED acute-migraine guideline** — the only non-pharmacologic intervention to reach Level A. Open [Greater Occipital Nerve Block](#/tree/occipital-nerve-block) for landmarks, aspiration check, agent selection, and post-procedure care.\n\n**DHE (dihydroergotamine) IV** — Raskin-style protocol: metoclopramide 10 mg IV first (anti-nausea pretreatment), then DHE 0.5-1 mg IV slow push. Repeat q8h × 3 days as an inpatient if status migrainosus is refractory.\n\n**DHE absolute contraindications:** pregnancy, CAD, uncontrolled HTN, triptan within 24 h, peripheral vascular disease, breastfeeding.\n\n**Disposition for true refractory status migrainosus:** admit for inpatient DHE protocol, neurology consult, IV magnesium, sleep + hydration, taper of any overused acute analgesics.","citation":[2,14,27],"recommendation":"ONB at bedside (first-tier); DHE if not contraindicated; admit if true status migrainosus.","confidence":"recommended","safetyLevel":"warning"}'::jsonb
WHERE id = 'hh-rescue-refractory' AND tree_id = 'headache-hub';

-- Node: hh-imaging (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Imaging Decision Cheat-Sheet","body":"You should NOT image every headache. Image when ANY of the following:\n\n**Indications for non-contrast CT head:**\n- First-or-worst / thunderclap onset\n- New HA in age ≥50\n- Focal deficit, AMS, seizure\n- Post-traumatic with red flags (Canadian CT Head Rule)\n- HIV / immunocompromised with new HA\n- Anticoagulated with new HA\n- Papilledema\n- Pattern change in a known primary HA disorder (new quality, location, or frequency)\n- Pregnancy + HA with any red flag (shield abdomen)\n\n**Add modality by suspicion:**\n- **CTA / MRA brain + neck:** suspected dissection ([Cervical Artery Dissection](#/tree/cervical-artery-dissection)), RCVS, vasculitis, vertebral pathology\n- **CT venogram or MRV:** suspected [CVST](#/tree/cvst), papilledema with negative CT\n- **MRI brain with contrast:** suspected mass, infection, MS, lower-grade pathology missed on CT (esp. posterior fossa)\n- **LP:** suspected [SAH](#/tree/sah) with negative CT >6 h from onset; suspected [Meningitis](#/tree/meningitis); idiopathic intracranial hypertension (opening pressure)\n\n**CT BEFORE LP indicated when:** decreased LOC · focal neurologic deficit · papilledema · immunocompromise · new-onset seizure (within 1 week) · history of CNS disease · age ≥60 (IDSA). Otherwise LP can proceed without CT.\n\n**Opening pressure matters — measure it every time you tap for headache.** Idiopathic intracranial hypertension (modified Dandy / Friedman 2013 criteria) requires an elevated OP with NORMAL CSF composition and no mass/hydrocephalus/venous thrombosis on neuroimaging: **≥25 cm H₂O in adults, ≥28 cm H₂O in children** (≥25 in a non-sedated, non-obese child). Measure lateral decubitus with legs extended; a Valsalva-ing or knees-to-chest patient falsely elevates the number. A LOW opening pressure (<6 cm H₂O) points the other way — spontaneous intracranial hypotension. Suspect IIH in an obese woman of childbearing age with daily HA, pulsatile tinnitus, transient visual obscurations, or papilledema — and get formal visual fields, because vision loss is the thing you are preventing.\n\n**Sensitivity caveats:**\n- Non-contrast CT for SAH: **100% (95% CI 97-100) within 6 h in the Perry 2011 cohort, pooled 98.7% across studies** — both conditioned on a modern (≥16-slice) scanner read by a qualified radiologist. Sensitivity drops sharply after 12-24 h. LP for xanthochromia is the rescue test after 6 h, but oxyhemoglobin does not fully convert to bilirubin until ~12 h, so a tap done between 6 and 12 h can be falsely reassuring — and most North American labs read xanthochromia visually (~83% sens) rather than by spectrophotometry (~87%).\n- CT misses cerebellar / posterior fossa pathology more often than MRI — low threshold to MRI if posterior fossa suspected.\n\n**No imaging needed:** recurrent benign-pattern HA in a known migraineur with no red flags; tension-type pattern with no SNNOOP10 features (this is where the checklist earns its keep — as a recall list when you are NOT imaging).","citation":[5,6,7,10,25,26,30],"next":"hh-dispo","summary":"Image when ANY red flag. CT first; CTA/MRV/MRI/LP by suspicion. CT-before-LP if AMS/focal/papilledema/immunocomp/new seizure/age ≥60. IIH opening pressure ≥25 cm H₂O adults, ≥28 children."}'::jsonb
WHERE id = 'hh-imaging' AND tree_id = 'headache-hub';

-- Node: hh-dispo (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":5,"title":"Disposition","body":"Common framework across undifferentiated HA. The deep-dive consults carry phenotype-specific admit criteria — defer to those once you commit.","citation":[7,1],"options":[{"label":"Discharge — pain controlled + tolerating PO + no red flags","description":"Standard pathway for benign-pattern HA after the cocktail","next":"hh-dispo-discharge"},{"label":"Observe — partial response, awaiting labs/imaging, or social barrier","description":"ED observation unit; reassess at 4-6 h","next":"hh-dispo-observe"},{"label":"Admit — red-flag workup positive, refractory, SI, pregnancy emergency","description":"Admit per the deep-dive consult’s admit criteria","next":"hh-dispo-admit","urgency":"urgent"}],"summary":"Discharge if controlled + PO + no flags. Observe if partial/pending. Admit per deep-dive consult criteria."}'::jsonb
WHERE id = 'hh-dispo' AND tree_id = 'headache-hub';

-- Node: hh-dispo-discharge (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":5,"title":"Discharge — Universal Checklist","body":"Before discharge:\n\n1. Pain reduced to an acceptable level (typically ≤3/10 or back to baseline)\n2. Tolerating PO\n3. Orthostatic vitals normal (prochlorperazine + diphenhydramine + ketorolac can drop BP)\n4. No new neurologic findings on recheck\n5. **Suicide screen** if cluster (highest SI of any primary HA), TN, chronic migraine, or mood-disorder features + chronic pain\n6. **Written return precautions covering:** first-or-worst severity · new neurologic symptom (weakness, numbness, vision/speech change) · fever or stiff neck · persistent vomiting · severe pain unresponsive to home Rx · any vision change · seizure\n7. **Follow-up arranged:** PCP 1-2 wks (new tension-type, mild migraine); Neurology 1-2 wks (new cluster, TN, refractory migraine, atypical features); OB/MFM (pregnancy-related); Ophthalmology (AACG, optic/visual concerns)\n8. **Consult-specific discharge bundle delivered** — see the relevant deep-dive (e.g., home O₂ + SQ sumatriptan for cluster; verapamil + ECG schedule for cluster maintenance; carbamazepine titration + lab plan for TN)\n\n**Counseling for the typical migraineur:** avoid daily analgesic use (medication-overuse HA: triptans/ergots ≥10 d/mo, simple analgesics ≥15 d/mo); sleep regularity, hydration, regular meals, stress management; trigger diary for 4-6 weeks if recurrent; prophylaxis referral if ≥4 HA days/mo.","citation":[7,1],"recommendation":"Discharge only after pain controlled, PO tolerated, no new neuro, written return precautions, follow-up arranged.","confidence":"definitive"}'::jsonb
WHERE id = 'hh-dispo-discharge' AND tree_id = 'headache-hub';

