INSERT INTO tree_citations (tree_id, num, text) VALUES ('monocular-vision-loss-hub', 8, 'Maz M, Chung SA, Abril A, Langford CA, Gorelik M, Guyatt G, et al. 2021 American College of Rheumatology/Vasculitis Foundation Guideline for the Management of Giant Cell Arteritis and Takayasu Arteritis. Arthritis Rheumatol. 2021;73(8):1349-1365. doi:10.1002/art.41774. PMID: 34235884. Free full text: https://pmc.ncbi.nlm.nih.gov/articles/PMC12344528/ (Basis for GCA glucocorticoid dosing in this hub: Rec 9 - pulse IV methylprednisolone 500-1000 mg daily x 3-5 days for threatened vision loss, conditional; Rec 11 - prednisone 1 mg/kg up to 80 mg daily for newly diagnosed GCA, conditional; Rec 3 - temporal artery biopsy within 2 weeks of starting glucocorticoids, conditional.)');
