INSERT INTO tree_citations (tree_id, num, text) VALUES ('monocular-vision-loss-hub', 11, 'Beck RW, Cleary PA, Anderson MM Jr, Keltner JL, Shults WT, Kaufman DI, et al.; Optic Neuritis Study Group. A randomized, controlled trial of corticosteroids in the treatment of acute optic neuritis. N Engl J Med. 1992;326(9):581-588. doi:10.1056/NEJM199202273260901. PMID: 1734247. (Basis for "no oral prednisone alone": standard-dose oral prednisone alone was ineffective and increased the rate of new optic neuritis attacks.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('monocular-vision-loss-hub', 12, 'Propst SL, Kirschner JM, Strachan CC, Roumpf SK, Menard LM, Sarmiento EJ, Hunter BR. Ocular Point-of-Care Ultrasonography to Diagnose Posterior Chamber Abnormalities: A Systematic Review and Meta-analysis. JAMA Netw Open. 2020;3(2):e1921460. doi:10.1001/jamanetworkopen.2019.21460. PMID: 32074291. https://jamanetwork.com/journals/jamanetworkopen/fullarticle/2761259');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('monocular-vision-loss-hub', 13, 'Rowh AD, Ufberg JW, Chan TC, Vilke GM, Harrigan RA. Lateral canthotomy and cantholysis: emergency management of orbital compartment syndrome. J Emerg Med. 2015;48(3):325-330. doi:10.1016/j.jemermed.2014.11.002. PMID: 25524455.');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('monocular-vision-loss-hub', 14, 'Preterre C, Gaultier A, Obadia M, Vignal C, Mourand I, Plat J, et al.; THEIA collaborators. Intravenous alteplase versus oral aspirin for acute central retinal artery occlusion within 4.5 h of severe vision loss (THEIA): a multicentre, double-dummy, patient-blinded and assessor-blinded, randomised, controlled, phase 3 trial. Lancet Neurol. 2025;24(11):909-919. doi:10.1016/S1474-4422(25)00308-4. PMID: 41109232. (n=70; primary endpoint >=0.3 logMAR improvement at 1 month: 19/29 [66%] alteplase vs 13/27 [48%] aspirin 300 mg PO; adjusted OR 1.1, 95% CI 0.07-18.39; p=0.95. Likely underpowered. One asymptomatic ICH in the alteplase arm.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('monocular-vision-loss-hub', 15, 'Ryan SJ, Jorstad OK, Skjelland M, Pesonen M, Simonsen CZ, Bek T, et al.; TenCRAOS Investigators. A Randomized Trial of Tenecteplase in Acute Central Retinal Artery Occlusion. N Engl J Med. 2026;394(5):442-450. doi:10.1056/NEJMoa2508515. PMID: 41604638. (n=78; tenecteplase 0.25 mg/kg vs aspirin 300 mg PO within 4.5 h. Vision recovery [BCVA <=0.7 logMAR] at 30 days: 8/40 [20%] vs 9/38 [24%]; risk difference -3.7 percentage points, 95% CI -22.0 to 14.7; p=0.69. More adverse events with tenecteplase including one fatal intracranial hemorrhage.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('monocular-vision-loss-hub', 16, 'Endophthalmitis Vitrectomy Study Group. Results of the Endophthalmitis Vitrectomy Study. A randomized trial of immediate vitrectomy and of intravenous antibiotics for the treatment of postoperative bacterial endophthalmitis. Arch Ophthalmol. 1995;113(12):1479-1496. PMID: 7487614. (n=420. No difference in final visual acuity or media clarity with vs without systemic ceftazidime/amikacin. Immediate vitrectomy benefited only the light-perception-only subgroup.)');
INSERT INTO tree_citations (tree_id, num, text) VALUES ('monocular-vision-loss-hub', 17, 'Abbas A, Sabet H, Abo-Elnour DE, Al-Mufti J, Aldehri M, Alnaami I, Nguyen TN. Effectiveness and safety of intravenous thrombolysis for non-arteritic central retinal artery occlusion: A GRADE-assessed meta-analysis. Graefes Arch Clin Exp Ophthalmol. 2026;264(6):1541-1558. doi:10.1007/s00417-026-07145-z. PMID: 41758379.');

-- Node: ovp-abnormal-vs (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Abnormal Vital Signs","body":"**Abnormal vitals strongly suggest organic etiology.** Do NOT attribute to \"anxiety\" without investigation.\n\n**Fever + behavioral change:**\n• Infection (UTI most common in elderly, meningitis, encephalitis)\n• Neuroleptic malignant syndrome (NMS)\n• Serotonin syndrome\n• Thyroid storm\n• **Hyperactive delirium with severe agitation** — hyperthermia + severe agitation + altered mental status + metabolic derangement. This is a true life threat: cool aggressively, sedate, check K+/lactate/CK, and watch for rhabdomyolysis and arrest.\n\n⚠️ **Terminology:** do NOT chart \"excited delirium.\" ACEP withdrew its 2009 excited-delirium white paper on 12 Oct 2023 and states the term should not be used clinically or in expert testimony. AMA, APA, AAEM, NAME, and ACMT have all disavowed it. The accepted descriptor is **hyperactive delirium with severe agitation** (ACEP Task Force Report, June 2021).\n\n**Tachycardia:**\n• Sympathomimetic toxidrome\n• Alcohol/benzo withdrawal\n• Thyrotoxicosis\n• PE (panic overlap)\n• Pheochromocytoma (mimics panic)\n\n**Hypertension:**\n• Stimulant intoxication\n• Withdrawal syndromes\n• Hypertensive encephalopathy\n\n**Hypoxia:**\n• PE, pneumonia, aspiration\n• CO toxicity (multiple patients same location)\n\nProceed with targeted workup based on vital sign pattern.","citation":[2,10,11],"next":"ovp-workup","summary":"Vital sign patterns guide differential - fever suggests infection/toxidrome, tachycardia suggests withdrawal/stimulants"}'::jsonb
WHERE id = 'ovp-abnormal-vs' AND tree_id = 'organic-vs-psych';

-- Node: ovp-red-flags (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Red Flags for Organic Cause","body":"[Red Flags Quick Reference](#/info/ovp-red-flags-summary)\n\n**High-risk features suggesting organic etiology:**\n\n• **New-onset psychiatric symptoms** without prior history\n• **Age >45** with first psychiatric presentation\n• **Age <12** with behavioral emergency\n• **Altered level of consciousness** (drowsy, obtunded)\n• **Fluctuating course** (waxes and wanes)\n• **Visual hallucinations** (rare in primary psych)\n• **Disorientation** (to person, place, time)\n• **Memory impairment** (recent memory)\n• **Focal neurologic deficits**\n• **Abnormal vital signs**\n• **Recent head trauma**\n• **Immunocompromised** (HIV, transplant, chemo)\n• **Catatonia** (immobility, mutism, posturing)\n\n**63% of patients with new-onset psychiatric symptoms had organic etiology** (Henneman 1994, n=100).\n\n⚠️ **Read that number correctly.** Henneman enrolled a narrow slice: alert, ages 16-65, urban county hospital, **first-episode psych symptoms only** — patients with known psych disease, obvious intoxication, medical complaints, and overdose were all excluded. And **28 of the 63 \"organic\" findings were a positive alcohol/drug screen**, not occult medical disease. Older series in broader psych populations found organic illness in only 4-12% (Dolan 1985, Koran 1988).\n\n**Bottom line:** 63% justifies aggressive workup in the true first-break patient. It does NOT justify shotgun labs on the known-schizophrenic having his usual relapse — that patient belongs in the Olshaker/ACEP targeted-testing lane.","citation":[2,5,6],"options":[{"label":"Red flags present","description":"High suspicion for organic cause - proceed to targeted workup","next":"ovp-workup","urgency":"urgent"},{"label":"No red flags","description":"Known psych history, similar presentation, normal exam","next":"ovp-low-risk"},{"label":"Elderly patient (≥65)","description":"Higher risk - delirium missed 76% of the time","next":"ovp-elderly","urgency":"urgent"}],"summary":"63% of new-onset psych symptoms have organic cause - visual hallucinations, fluctuation, disorientation suggest delirium"}'::jsonb
WHERE id = 'ovp-red-flags' AND tree_id = 'organic-vs-psych';

-- Node: ovp-organic-mimics (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Medical Conditions Mimicking Psychiatric Illness","body":"[AEIOU-TIPS Mnemonic](#/info/ovp-aeiou-tips)\n\n**Neurologic:**\n• Encephalitis (autoimmune increasing - present with psychosis, catatonia)\n• Complex partial seizures (postictal state, temporal lobe)\n• Stroke/TIA (frontal, temporal)\n• Subdural hematoma (especially elderly on anticoagulants)\n• Neurosyphilis (US syphilis rose ~80% from 2018 to 2022; 209,253 total cases in 2023 remains the most since 1950, though primary/secondary syphilis fell 10% in 2023 and a further 22% in 2024 — the first sustained decline since 2001. Congenital syphilis has risen 12 straight years.)\n• Parkinson disease (psychiatric symptoms precede motor)\n• Huntington disease\n\n**Endocrine:**\n• Thyroid (hyper = anxiety 60%; hypo = depression, \"myxedema madness\")\n• Hypoglycemia, hyperglycemia\n• Cushing syndrome (depression, anxiety in 50%+)\n• Pheochromocytoma (mimics panic attacks)\n• Adrenal insufficiency\n\n**Metabolic:**\n• Hyponatremia (common, especially elderly on diuretics/SSRIs)\n• Hypercalcemia\n• Uremia, hepatic encephalopathy\n• B12 deficiency (depression, psychosis, OCD)\n\n**Infectious:**\n• UTI (most common delirium trigger in elderly women)\n• Pneumonia\n• Sepsis\n• HIV-related CNS infections","citation":[5,10],"next":"ovp-workup","summary":"Thyroid, glucose, sodium, B12, UTI are common mimics - encephalitis and neurosyphilis are re-emerging"}'::jsonb
WHERE id = 'ovp-organic-mimics' AND tree_id = 'organic-vs-psych';

-- Node: ovp-elderly (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Elderly Patient (≥65 years)","body":"**Delirium is missed 76% of the time** in ED elderly patients (Han 2009).\n\n**Prevalence: 8-17% of older ED patients**, with pooled meta-analytic estimates clustering ~15% and large recent cohorts at 14-16%. The full published range is 7-35% depending on screening method. **Up to 40% in patients arriving from a nursing home.** New psychiatric symptoms in the elderly = delirium until proven otherwise.\n\n**Common precipitants in elderly:**\n• UTI (most common in women)\n• Medications (anticholinergics, benzos, opioids, polypharmacy)\n• Dehydration\n• Constipation/urinary retention\n• Pneumonia\n• Metabolic (Na, glucose, Ca)\n• Acute coronary syndrome (ACS can present as confusion)\n• Stroke\n\n**Highest-yield risk factors (high-certainty evidence):** nursing home residence (OR 3.45), known cognitive impairment (OR 4.46), prior stroke (OR 3.20), hearing impairment (OR 2.57). ED length of stay >10 h itself raises risk (OR 2.23).\n\n**Screen with CAM or bCAM:**\n[CAM Screening Tool](#/info/ovp-cam-tool)\n\n• bCAM: 84% sensitive, 96% specific when performed by physician\n• Takes <2 minutes\n\n**Geriatric ED Guidelines 2.0 (Acad Emerg Med 2026):** 4AT, bCAM, CAM-ICU, mCAM, AMT-4, or RASS may each be used to rule delirium in or out. The Delirium Triage Screen may be used to **rule out only — it cannot rule in.** All recommendations are conditional (very low certainty; ED evidence base is thin).\n\n**If CAM positive or uncertain:** Admit for medical workup. Do NOT send to psychiatric facility.","citation":[6,9,12,13],"next":"ovp-workup","calculatorLinks":[{"id":"cam-icu","label":"CAM-ICU"}],"summary":"Elderly + behavioral change = delirium until proven otherwise. UTI is #1 cause in elderly women."}'::jsonb
WHERE id = 'ovp-elderly' AND tree_id = 'organic-vs-psych';

-- Node: ovp-pending (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Workup Pending","body":"**While awaiting results:**\n\n• Continue monitoring vital signs\n• Maintain safe environment\n• Avoid physical restraints if possible (worsens delirium)\n• Verbal de-escalation preferred\n• If sedation needed, avoid benzodiazepines (worsen delirium) - use antipsychotics\n\n⚠️ **Three exceptions where that rule inverts — benzodiazepines are the DRUG OF CHOICE, not the drug to avoid:**\n1. **Alcohol or sedative-hypnotic withdrawal** (including benzo withdrawal) — benzos are first-line and withholding them risks seizure and DTs.\n2. **Sympathomimetic/stimulant toxicity** (cocaine, methamphetamine, synthetic cathinones) — benzos treat the underlying adrenergic storm; antipsychotics lower the seizure threshold and impair heat dissipation.\n3. **Catatonia** — lorazepam challenge is both diagnostic and therapeutic; antipsychotics can precipitate malignant catatonia/NMS.\n\nIf you cannot exclude these, do not reflexively reach for the antipsychotic.\n\n**Severe agitation, per ACEP 2024 (Level B):** droperidol + midazolam, or an atypical antipsychotic + midazolam, works fastest. Single agent = droperidol or an atypical antipsychotic (midazolam alone has the worst adverse-effect profile). Ketamine (Level C) when patient/staff safety demands immediate control — only with airway and resuscitation capability at the bedside. These recommendations do NOT extend to patients >65, pregnant patients, or children.\n\n**Document clearly:**\n• \"Patient remains under observation pending medical workup\"\n• \"Not medically cleared for psychiatric facility\"\n\n**Do NOT transfer to psychiatric facility** with pending workup or abnormal vital signs.\n\n**Repeat assessment** after results return.","citation":[2,3,14],"next":"ovp-workup","summary":"Do not transfer to psych facility with pending workup - continue monitoring and reassess"}'::jsonb
WHERE id = 'ovp-pending' AND tree_id = 'organic-vs-psych';

