-- Node: pst-withdrawal (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Withdrawal Pathway","body":"**→ [Alcohol Withdrawal Consult](#/tree/alcohol-withdrawal)**\n\n**Early treatment prevents:**\n• Withdrawal seizures (peak 12-48h)\n• Delirium tremens (peak 48-96h)\n\n**DT mortality — say the number correctly:** untreated DTs historically carried 15-37% mortality. With modern ICU care, aggressive benzodiazepine/phenobarbital treatment, and correction of electrolytes, mortality is roughly **1-4%**. Quote the low number only for the patient who is actually being treated.\n\n**Which substance?**\n• **Alcohol/Benzos:** CIWA-Ar, benzodiazepines, phenobarbital\n• **Opioids:** COWS score, buprenorphine initiation, clonidine\n• **Stimulants:** Supportive care, benzos for agitation\n\n**High-risk features:** Prior seizures/DTs, PAWSS ≥4, prolonged heavy use","citation":[6],"next":"pst-end","summary":"Withdrawal — route to Alcohol Withdrawal consult for CIWA-Ar and benzo protocols."}'::jsonb
WHERE id = 'pst-withdrawal' AND tree_id = 'psych-triage';

-- Node: pst-eating (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Eating Disorder Pathway","body":"**Eating disorder emergency — focus on medical stability:**\n\n**Check immediately:**\n• Electrolytes: K+, PO4, Mg2+ (refeeding risk)\n• ECG: QTc prolongation, bradycardia\n• Glucose\n• Vitals: Bradycardia, orthostatic hypotension\n\n**High-risk features that should trigger admission (legacy MARSIPAN 2014 thresholds):**\n• BMI <13 or rapid weight loss >1 kg/week\n• K+ <3.0 or PO4 <0.5\n• HR <40 or BP <90 systolic\n• QTc >450 ms\n• Syncope\n• Hypoglycemia\n\n⚠️ **Guideline update — MARSIPAN is retired.** The Royal College of Psychiatrists replaced MARSIPAN (CR189) and Junior MARSIPAN (CR168) with **MEED — Medical Emergencies in Eating Disorders, College Report CR233 (May 2022)**. MEED deliberately moves away from single absolute cutoffs like BMI and instead uses a **red / amber / green risk matrix** across BMI/weight trajectory, cardiovascular status, hydration, muscle power (sit-up–squat–stand), ECG, biochemistry, and engagement. **Any one RED item, or two or more AMBER items, marks a high-risk patient who warrants urgent medical admission** — a patient can be high risk at a BMI well above 13. Use the numbers above as a floor, not a ceiling, and check the current MEED matrix for the case in front of you.\n\n**Refeeding syndrome risk:** Start feeding slowly, monitor PO4/K+/Mg2+ daily × 3 days","citation":[10],"next":"pst-end","summary":"Eating disorder — check electrolytes, ECG, vitals. MEED CR233 risk matrix (any red or 2+ amber = admit). Refeeding syndrome risk."}'::jsonb
WHERE id = 'pst-eating' AND tree_id = 'psych-triage';

