-- Node: uls-triage (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Rule In / Rule Out — Pick the Thread","body":"Work the limb- and life-threats first, then DVT, then the benign mimics. Each branch runs a validated tool or a tight clinical gate to an explicit verdict; excluded branches return here for the next differential.","citation":[1],"options":[{"label":"🔴 Cold / pale / pulseless / painful limb","description":"Acute limb ischemia","next":"uls-ischemia-entry","urgency":"critical"},{"label":"🔴 Tense, dusky/cyanotic, severely swollen painful limb","description":"Phlegmasia cerulea dolens (massive DVT)","next":"uls-phlegmasia-entry","urgency":"critical"},{"label":"🔴 Pain out of proportion / crepitus / dusky skin / toxicity","description":"Necrotizing soft-tissue infection","next":"uls-necfasc-entry","urgency":"critical"},{"label":"Tense compartment / pain on passive stretch (often post-trauma)","description":"Compartment syndrome","next":"uls-compartment-entry","urgency":"critical"},{"label":"Swollen calf, DVT risk factors ± chest symptoms / hypoxia","description":"DVT (± PE)","next":"uls-dvt-entry","urgency":"urgent"},{"label":"Asymmetric edema + heart failure / dyspnea / raised JVP","description":"Right-heart failure","next":"uls-rhf-entry","urgency":"urgent"},{"label":"Warm/well, no limb threat, no systemic signs","description":"Benign mimics (cellulitis / Baker cyst / venous)","next":"uls-benign-entry","urgency":"routine"},{"label":"None fit — undifferentiated, stable","description":"Initial bundle + reassess","next":"uls-rescue","urgency":"routine"}],"summary":"Eight-branch triage: acute ischemia / phlegmasia / necrotizing infection / compartment syndrome / DVT±PE / right-heart failure / benign / undifferentiated."}'::jsonb
WHERE id = 'uls-triage' AND tree_id = 'unilateral-leg-swelling-hub';

-- Node: uls-necfasc-entry (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Necrotizing Soft-Tissue Infection — Toxicity Gate","body":"**\"Cellulitis\" that hurts far more than it looks is a necrotizing infection until proven otherwise.** The alarm signs: **pain out of proportion to exam, systemic toxicity, crepitus, dusky/bullous/necrotic skin, rapidly spreading erythema, or firm \"woody\" induration beyond the erythema.** \n\n⚠️ **LRINEC IS NOT A RULE-OUT TEST.** Pooled meta-analysis (23 studies, n=5,982): LRINEC **≥6 sensitivity only 68.2%** (specificity 84.8%); **≥8 sensitivity 40.8%** (specificity 94.9%). A LRINEC below threshold misses roughly **1 in 3 surgically confirmed** necrotizing infections. Individual exam findings are worse still — fever sens 46%, hemorrhagic bullae 25%, hypotension 21%. **CT is the best-performing study (sens 88.5%, spec 93.3%) but a normal CT does not exclude it either.** LRINEC may raise suspicion; it must NEVER lower it. **Do NOT wait for imaging or labs to consult surgery** when the exam is convincing — surgical exploration is the diagnostic gold standard. [7]","citation":[4,7],"options":[{"label":"Pain out of proportion + toxicity / crepitus / dusky or bullous skin","description":"Resuscitate + emergent surgery","next":"uls-necfasc-verdict","urgency":"critical"},{"label":"Erythema/warmth proportional to pain, no toxicity/crepitus","description":"Necrotizing infection unlikely — move on","next":"uls-necfasc-excluded","urgency":"routine"}],"summary":"Pain out of proportion + toxicity + crepitus/skin necrosis = necrotizing infection; emergent surgery, do not wait for imaging.","safetyLevel":"critical"}'::jsonb
WHERE id = 'uls-necfasc-entry' AND tree_id = 'unilateral-leg-swelling-hub';

-- Node: uls-necfasc-excluded (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Necrotizing Infection — Unlikely","body":"Erythema and warmth proportional to the pain, no systemic toxicity, and no crepitus/skin necrosis make a necrotizing infection unlikely right now. **It evolves fast** — if pain out of proportion, toxicity, crepitus, or skin necrosis appears on reassessment, resuscitate and consult surgery immediately. (Ordinary cellulitis is handled in the benign branch.)\n\n⚠️ **\"Unlikely\" is a clinical judgment, not a test result.** No score or scan safely rules this out — **LRINEC ≥6 is only 68% sensitive and CT is 88.5% sensitive.** Neither a low LRINEC nor a normal CT should reassure you if the exam or the trajectory is worrying. **Re-examine in person, and document the reassessment.** [7]\n\nReturn to the hub for the next differential.","citation":[4,7],"next":"uls-triage","recommendation":"Necrotizing infection unlikely without toxicity/skin signs; re-examine and escalate immediately if it evolves. A low LRINEC or normal CT does NOT rule it out.","confidence":"recommended","safetyLevel":"warning"}'::jsonb
WHERE id = 'uls-necfasc-excluded' AND tree_id = 'unilateral-leg-swelling-hub';

-- Node: uls-dvt-entry (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"DVT — Wells + Chest-Symptom Gate","body":"**Risk-stratify with the Wells DVT score** (in the toolbar), then combine with D-dimer and ultrasound.\n\n**Wells DVT — two-tier model (the one that pairs with D-dimer):**\n- **DVT UNLIKELY (Wells ≤1)** + negative high-sensitivity D-dimer → **DVT excluded**, no imaging needed.\n- **DVT LIKELY (Wells ≥2)** → **go straight to compression ultrasound. A negative D-dimer does NOT exclude DVT in this group — do not use it to skip imaging.**\n- (Original three-tier equivalents: low ≤0, moderate 1–2, high ≥3. If you are using the three-tier score, only the LOW tier is D-dimer-excludable.)\n\n⚠️ **D-DIMER UNIT TRAP — a 2× error waiting to happen.** The conventional cutoff of **500 ng/mL FEU** (fibrinogen equivalent units) equals **250 ng/mL DDU** (D-dimer units). Confirm which unit your lab reports before you act on the number — reading a DDU result against an FEU cutoff misses clots; the reverse over-images.\n- **Age-adjusted D-dimer (age >50, LOW/UNLIKELY probability only):** **age × 10 = cutoff in ng/mL (µg/L) FEU.** If your lab reports **DDU, the multiplier is age × 5.** ADJUST-PE failure rate 0.3%. [8]\n- **Never age-adjust, and never use D-dimer at all, in a Wells-LIKELY patient.** [6]\n\n**First, screen for PE:** any pleuritic chest pain, dyspnea, hypoxia, syncope, or tachycardia with the swollen leg points to a concurrent pulmonary embolism.\n\n**🤰 Pregnancy / postpartum — the rules change.** D-dimer rises physiologically and is **not validated to exclude DVT in pregnancy — image, do not rule out on a number.** **~85% of pregnancy DVT is LEFT-sided**, because the gravid uterus and the right common iliac artery compress the left common iliac vein (the same anatomy as **May-Thurner syndrome**, which does this in the non-pregnant young patient). **Isolated iliac vein DVT can be missed entirely by standard proximal compression ultrasound** — with left leg + buttock/flank/back pain or whole-leg swelling, ask for iliac views, or MR/CT venography. The **LEFt** rule (Left leg symptoms, calf circumference difference ≥2 cm = Edema, First trimester onset) risk-stratifies but is NOT a stand-alone rule-out. [12]","citation":[6,8,12],"options":[{"label":"Swollen leg + chest pain / dyspnea / hypoxia","description":"Suspect concurrent PE","next":"uls-pe-verdict","urgency":"critical"},{"label":"DVT confirmed on ultrasound (or high Wells + positive D-dimer pending US)","description":"Treat as DVT","next":"uls-dvt-verdict","urgency":"urgent"},{"label":"Low Wells + negative D-dimer (or negative US)","description":"DVT excluded — move on","next":"uls-dvt-excluded","urgency":"routine"}],"summary":"Wells ≤1 + neg D-dimer excludes; Wells ≥2 → US (D-dimer cannot exclude). Check FEU vs DDU units. Chest symptoms → screen PE.","safetyLevel":"warning"}'::jsonb
WHERE id = 'uls-dvt-entry' AND tree_id = 'unilateral-leg-swelling-hub';

-- Node: uls-dvt-verdict (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"DVT — Anticoagulate + Risk-Stratify","body":"Open [DVT](#/tree/dvt) for the full pathway and dosing in special populations.\n\n**Next steps:**\n- **Start anticoagulation** (DOAC first-line for most; LMWH/heparin where a DOAC is unsuitable — pregnancy, severe renal disease, antiphospholipid syndrome, some active cancer per shared decision) unless a contraindication exists.\n\n**Single-drug DOAC regimens for acute PROXIMAL DVT (no heparin lead-in required):** [9]\n- **Apixaban 10 mg PO BID × 7 days, then 5 mg PO BID.** With or without food. Lowest GI bleeding risk.\n- **Rivaroxaban 15 mg PO BID × 21 days, then 20 mg PO once daily — TAKE WITH FOOD.** ⚠️ **Absorption of the 15/20 mg doses falls substantially when taken fasting; \"with food\" is part of the dose, not a comfort tip.**\n- (Edoxaban and dabigatran both require **5–10 days of parenteral lead-in first** — do not start them as monotherapy from the ED.)\n- **Minimum treatment phase for acute VTE: 3 months.** [9]\n\n**Isolated distal (calf) DVT — do NOT reflexively anticoagulate.** CHEST 2021: [9]\n- **No severe symptoms and no risk factors for extension** → **serial imaging over 2 weeks** (repeat US weekly, or sooner if symptoms worsen) is *suggested over* anticoagulation.\n- **Severe symptoms OR risk factors for extension** (active cancer, prior VTE, immobility, extensive/multi-vein clot, markedly raised D-dimer, inpatient) → anticoagulate, same regimen as proximal DVT.\n- On serial imaging: **no extension → stop (strong rec); extension into proximal veins → anticoagulate (strong rec).**\n\n**Disposition:** most uncomplicated lower-extremity DVTs are managed as outpatients; **admit for phlegmasia, extensive iliofemoral clot, high bleeding risk, severe pain, poor follow-up, or concurrent PE with RV strain.**\n- **Iliofemoral DVT** — consider vascular/IR discussion re: catheter-directed therapy in severe or limb-threatening cases, and look for **May-Thurner** compression in a young patient with a left-sided iliofemoral clot.\n- Consider whether an **unprovoked** DVT warrants a malignancy/thrombophilia workup on follow-up.\n- Provocation review, leg elevation, and return precautions (worsening swelling, chest symptoms).","citation":[6,9],"recommendation":"Anticoagulate proximal DVT (apixaban 10 mg BID × 7d → 5 mg BID, or rivaroxaban 15 mg BID × 21d → 20 mg daily WITH FOOD; minimum 3 months) + risk-stratify for outpatient vs admission. Isolated distal DVT: serial imaging × 2 weeks if mild and low-risk, anticoagulate if severe symptoms or extension risk. Return precautions for PE.","confidence":"recommended","safetyLevel":"warning"}'::jsonb
WHERE id = 'uls-dvt-verdict' AND tree_id = 'unilateral-leg-swelling-hub';

-- Node: uls-dvt-excluded (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"DVT — Excluded","body":"**Wells UNLIKELY (≤1) + negative high-sensitivity D-dimer** excludes DVT with a high negative predictive value (3-month VTE rate <1%). No imaging, no anticoagulation.\n\n⚠️ **A negative ultrasound does NOT automatically exclude DVT — it depends which study you got.** [6]\n- **Negative WHOLE-LEG (complete) compression US** → DVT excluded; no repeat scan needed.\n- **Negative PROXIMAL or 2-POINT compression US in a Wells-LIKELY (≥2) patient** → **NOT excluded.** Proximal-only imaging does not see the calf veins, and ~8–15% of isolated distal thrombi propagate. **Arrange a repeat proximal compression ultrasound at 5–7 days** (ASH 2018: one additional US at ~1 week), or obtain a whole-leg study now. Book the appointment before the patient leaves.\n- **Caution on bedside 2-point POCUS:** it images only the common femoral and popliteal segments and **can miss isolated femoral-vein DVT.** In inexperienced hands sensitivity has been reported as low as 63%. A negative 2-point scan in a high-suspicion patient needs a formal study.\n- **Left leg + pelvic/flank/back pain, pregnancy, or whole-leg swelling with a \"negative\" US** → think **isolated iliac vein DVT / May-Thurner**, which standard compression US does not reach. Escalate to iliac views or MR/CT venography.\n\nReturn to the hub for the next differential (benign mimics).","citation":[6,9],"next":"uls-triage","recommendation":"DVT excluded by Wells ≤1 + negative D-dimer, or by a negative WHOLE-LEG US. A negative proximal/2-point US in a Wells-likely patient is NOT exclusion — repeat compression US at 5–7 days or get a whole-leg study.","confidence":"recommended","safetyLevel":"warning"}'::jsonb
WHERE id = 'uls-dvt-excluded' AND tree_id = 'unilateral-leg-swelling-hub';

-- Node: uls-benign-entry (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Benign Mimics — Characterize","body":"**Once the limb- and life-threats are excluded, sort the common causes** — but keep the safety nets up (cellulitis can be early necrotizing infection; a \"Baker cyst\" swelling can hide a DVT).\n- **Cellulitis:** warm, tender, spreading erythema ± fever, often a portal of entry; **usually unilateral — bilateral lower-leg \"cellulitis\" is more often venous stasis dermatitis.** ⚠️ **~30% of patients admitted with \"lower-extremity cellulitis\" actually have pseudocellulitis** (Weng, JAMA Dermatol 2017: 79/259 misdiagnosed; 85% of those admitted did not need admission and 92% got unnecessary antibiotics). Commonest mimics: **stasis dermatitis (bilateral, chronic, itchy > painful, no fever), lymphedema, contact dermatitis, gout, DVT.** The **ALT-70** score (Asymmetry 3, Leukocytosis 1, Tachycardia 1, Age ≥70 = 2) supports the call but is only ~61% sensitive / ~71% specific — use it as a prompt to re-look, not a verdict. [11]\n- **Ruptured Baker cyst:** sudden calf pain/swelling ± a crescent bruise below the malleolus (positive Crescent sign); ultrasound distinguishes it from DVT.\n- **Superficial vein thrombosis (thrombophlebitis):** a tender palpable cord along a superficial vein. **This is NOT automatically benign.** Get a compression ultrasound and record **(a) the length of the thrombus and (b) its distance from the saphenofemoral / saphenopopliteal junction** — those two numbers decide whether it is anticoagulated (see the verdict node). Up to ~25% have concurrent DVT or PE at presentation.\n- **Chronic venous insufficiency / lymphedema:** chronic swelling, skin changes, often longstanding — a diagnosis of exclusion here.","citation":[1,11],"options":[{"label":"Warm spreading erythema + tenderness ± fever","description":"Cellulitis","next":"uls-cellulitis-verdict","urgency":"urgent"},{"label":"Sudden calf pain/swelling, DVT excluded on US, or chronic venous/lymphedema","description":"Baker cyst / venous / lymphedema","next":"uls-benign-verdict","urgency":"routine"}],"summary":"Sort benign mimics; ~30% of \"cellulitis\" is pseudocellulitis; measure SVT length and distance from the SFJ. Keep DVT and nec-fasc safety nets up."}'::jsonb
WHERE id = 'uls-benign-entry' AND tree_id = 'unilateral-leg-swelling-hub';

-- Node: uls-cellulitis-verdict (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Cellulitis — Antibiotics + Reassess Safety Nets","body":"**Cellulitis** (no dedicated consult yet — manage here):\n\n- **Empiric antibiotics** covering streptococci ± staphylococci (add MRSA cover for purulence, penetrating trauma, or risk factors); mark the erythema border and reassess.\n- **Re-confirm this is NOT a necrotizing infection** — pain out of proportion, toxicity, crepitus, or rapid spread → back to the necrotizing branch and surgery.\n- **Before you commit to antibiotics, ask whether this is pseudocellulitis.** ~30% of admissions labelled lower-extremity cellulitis are something else. **Bilateral, symmetric, itchy, afebrile, chronic, or non-tender → it is almost certainly stasis dermatitis, not infection** — true cellulitis is nearly always unilateral and acutely painful. Treat stasis dermatitis with compression, elevation, and topical steroid, not antibiotics. [11]\n- **Exclude a coexisting DVT** if swelling is prominent — they can coexist and cellulitis is a DVT risk factor.\n- Elevation, treat the portal of entry (tinea, ulcers), analgesia; admit for systemic toxicity, immunocompromise, or failed outpatient therapy.\n- **If there is no improvement at 48–72 h, do not just escalate antibiotics — re-open the differential** (pseudocellulitis, DVT, abscess, necrotizing infection).\n- (Consult gap — managed in-hub.)","citation":[1,4,11],"next":"uls-disposition","recommendation":"Empiric strep±staph (MRSA if purulent) abx, mark and reassess; actively consider pseudocellulitis (bilateral/itchy/afebrile = stasis dermatitis, not infection); keep necrotizing-infection and DVT safety nets up; admit if toxic/failing.","confidence":"recommended","safetyLevel":"warning"}'::jsonb
WHERE id = 'uls-cellulitis-verdict' AND tree_id = 'unilateral-leg-swelling-hub';

-- Node: uls-benign-verdict (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Baker Cyst / Venous / Lymphedema — Symptomatic Care + Follow-Up","body":"**Ruptured Baker cyst, superficial thrombophlebitis, chronic venous insufficiency, or lymphedema** (no dedicated consult yet — manage here) in a well patient with the emergencies excluded:\n\n- **Ruptured Baker cyst:** confirm with ultrasound (and exclude DVT), then symptomatic care — rest, ice, elevation, NSAIDs, compression; treat the underlying knee arthropathy.\n- **Superficial vein thrombosis (SVT) — decide by ULTRASOUND length and distance from the junction, not by how it looks:** [10]\n  - **Within 3 cm of the saphenofemoral (or saphenopopliteal) junction** → treat as a deep-system event: **therapeutic-dose anticoagulation** and vascular follow-up. This is the highest-risk group and was excluded from the SVT trials.\n  - **≥5 cm long and >3 cm from the junction** → **prophylactic-dose anticoagulation × 45 days.** CALISTO regimen: **fondaparinux 2.5 mg SC once daily × 45 days** (85% relative risk reduction in symptomatic VTE vs placebo). Rivaroxaban 10 mg PO daily or prophylactic/intermediate-dose LMWH × 45 days are accepted alternatives.\n  - **<5 cm, remote from the junction, no VTE risk factors** → supportive care: NSAIDs, warm compresses, compression, elevation.\n  - ⚠️ **Do not shorten the course.** Regimens of ≤14 days carry markedly higher VTE complication rates.\n- **Chronic venous insufficiency / lymphedema:** compression therapy, skin care, elevation, and outpatient vascular/lymphedema follow-up; this is a diagnosis of exclusion once DVT and the emergencies are ruled out.\n- Return precautions for new/worsening swelling, chest symptoms, fever, or increasing pain.\n- (Consult gap — managed in-hub.)","citation":[1,10],"next":"uls-disposition","recommendation":"Symptomatic care + compression + outpatient follow-up for Baker cyst / venous / lymphedema; US-confirm and exclude DVT. Superficial vein thrombosis: within 3 cm of the SFJ → therapeutic anticoagulation; ≥5 cm and >3 cm from the junction → fondaparinux 2.5 mg SC daily × 45 days; <5 cm and remote → supportive care.","confidence":"recommended"}'::jsonb
WHERE id = 'uls-benign-verdict' AND tree_id = 'unilateral-leg-swelling-hub';

-- Node: uls-rescue (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Initial Bundle","body":"**The swollen-leg work-up bundle (scale to acuity):**\n- **Focused exam:** pulses and skin color/temperature of BOTH legs, compartment tension, pain on passive stretch, calf circumference, portal of entry, and chest symptoms / hypoxia.\n- **Wells DVT score + D-dimer + compression ultrasound** — the DVT pathway (Wells in the toolbar). **Check whether your D-dimer is reported in FEU (cutoff 500 ng/mL) or DDU (cutoff 250 ng/mL) before interpreting it**, and remember D-dimer only excludes in the Wells-UNLIKELY (≤1) patient.\n- **Vitals + qSOFA** if any toxicity; resuscitate and screen for necrotizing infection / sepsis.\n- **Bloods:** CBC, renal function/electrolytes, CK (compartment/crush), lactate if toxic; consider BNP and troponin if cardiac.\n- **Anticoagulation** early for confirmed DVT / ischemia / phlegmasia (unless contraindicated).\n- Analgesia; NPO + IV access for anyone potentially heading to the OR (ischemia, phlegmasia, necrotizing infection, compartment).","citation":[1,6],"next":"uls-reassess"}'::jsonb
WHERE id = 'uls-rescue' AND tree_id = 'unilateral-leg-swelling-hub';

-- Node: uls-imaging (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Imaging","body":"**Match the study to the question:**\n- **Compression ultrasound with Doppler** — the primary test for DVT; also distinguishes a ruptured Baker cyst and assesses superficial veins. **Specify what you want: WHOLE-LEG (complete) US needs no repeat if negative; a PROXIMAL or 2-point study in a Wells-LIKELY patient needs a repeat scan at 5–7 days if negative.** For SVT, ask for thrombus length and distance from the saphenofemoral junction.\n- **CT / MR venography** — when **isolated iliac vein DVT** is the concern (pregnancy, left leg + pelvic/back pain, whole-leg swelling, suspected May-Thurner). Standard compression US does not reliably reach the iliac veins.\n- **CT / CT angiography** — for acute limb ischemia (arterial anatomy) and CT pulmonary angiography for suspected PE; can map necrotizing infection or an iliofemoral clot (phlegmasia) if it will not delay intervention.\n- **Compartment pressure measurement** — not imaging, but the confirmatory test for uncertain compartment syndrome (delta pressure <30 mmHg).\n- **Do NOT delay definitive surgery** (ischemia, phlegmasia thrombectomy, necrotizing-infection debridement, fasciotomy) for imaging when the exam is convincing. **A normal CT does not exclude a necrotizing infection** (sens 88.5%) — surgical exploration is the gold standard.","citation":[1,6,7],"next":"uls-disposition"}'::jsonb
WHERE id = 'uls-imaging' AND tree_id = 'unilateral-leg-swelling-hub';

-- Node: uls-dispo-discharge (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":5,"title":"Discharge","body":"**Discharge** the well patient with a clear plan.\n\n- **Uncomplicated DVT:** DOAC started (**apixaban 10 mg BID × 7 d → 5 mg BID**, or **rivaroxaban 15 mg BID × 21 d → 20 mg daily, WITH FOOD**), outpatient management confirmed, anticoagulation follow-up, and **strict PE return precautions** (chest pain, dyspnea, syncope). Confirm the patient can actually obtain and afford the drug before discharge.\n- **Negative PROXIMAL/2-point US but Wells-LIKELY:** **the repeat compression ultrasound at 5–7 days must be booked before the patient leaves** — an unbooked \"come back in a week\" is a missed DVT waiting to happen.\n- **Cellulitis:** empiric antibiotics, erythema border marked, elevation, follow-up in 48–72 h, and return precautions for spread/toxicity (reconsider necrotizing infection) or worsening swelling (reconsider DVT).\n- **Baker cyst / venous / lymphedema:** symptomatic care, compression, and outpatient vascular/lymphedema follow-up.\n- Written return precautions and a named follow-up; explicit DVT/PE and limb-threat red-flag counseling.","citation":[1,6,9],"recommendation":"Discharge benign/uncomplicated patients with anticoagulation or antibiotics as indicated, compression, and explicit PE / limb-threat return precautions. Book the 5–7 day repeat US before discharge if the negative study was proximal/2-point in a Wells-likely patient.","confidence":"recommended"}'::jsonb
WHERE id = 'uls-dispo-discharge' AND tree_id = 'unilateral-leg-swelling-hub';

